// Views
// ------------------------------------------------------------------
function clearAuthenticatedClientState() {
  // Close every authenticated overlay immediately. A session can expire while a
  // modal is open; hiding only the page underneath would leave the old account's
  // data visible above the login form.
  document.querySelectorAll('.overlay').forEach((node) => node.classList.add('hidden'));
  if (state.activitySource) { try { state.activitySource.close(); } catch (_) {} state.activitySource = null; }
  state.activityEvents = [];
  state.activityRetained = 0;
  state.activityInitialized = false;
  state.undoItems = [];
  state.undoLoading = false;
  state.allShares = [];
  state.linkShares = []; state.imageShares = []; state.lastSharesScope = '';
  state.photosData = [];
  state.albumsData = [];
  state.historyData = [];
  state.dashboardData = null;
  state.dashboardLiveData = null;
  state.imagesDashData = null;
  state.diagnosticsData = null;
  state.meta = null;
  state.settings = {};
  state.photoDimsCache = {};
  state.photoExifCache = {};
  state.photoOcrMatches = new Set();
  state.selShares.clear();
  state.photoSelection.clear();
  state.lastSharesJson = '';
  state.sharesLoaded = false;
  state.lastPhotosSig = '';
  state.lastSettingsJson = '';
  state.lastTransfersJson = '';
  state.lastHistoryMetaSig = '';
  state.lastPhotoHistoryMetaSig = '';
  // Clear password/sensitive editable fields retained by hidden modals. They are
  // rehydrated from the new principal's server state when opened again.
  document.querySelectorAll('.overlay input[type="password"], .overlay input[type="file"], .overlay textarea, #config-page input[type="password"], #config-page input[type="file"], #config-page textarea').forEach((node) => { try { node.value = ''; } catch (_) {} });
  // The connector wizard can hold a Google service-account private key in memory and
  // account-specific text fields. Clear both JS state and every editable/output field
  // on principal changes so a later account cannot inherit a hidden credential.
  try {
    stopConnectorConfigPoll();
    connectorConfigSession = null; connectorConfigPendingGoogle = null; connectorGoogleServiceAccount = null;
    connectorConfigCloseAuthWindow();
    const wizard = $('connector-remote-wizard'); if (wizard) wizard.classList.add('hidden');
    document.querySelectorAll('#connector-remote-wizard input, #connector-remote-wizard textarea').forEach((node) => { try { node.value = ''; } catch (_) {} });
    const serviceEmail = $('connector-config-google-service-email'); if (serviceEmail) serviceEmail.textContent = '';
    const serviceInfo = $('connector-config-google-service-info'); if (serviceInfo) serviceInfo.classList.add('hidden');
    const configStatus = $('connector-config-status'); if (configStatus) { configStatus.textContent = ''; configStatus.className = 'muted sm'; }
  } catch (_) {}
  try { renderTransfers([]); } catch (_) {}
  try { renderHistory([]); } catch (_) {}
  try { renderShares([]); } catch (_) {}
  try { renderActivity(); } catch (_) {}
  // Configuration is now a full page rather than an overlay. Clear account-specific
  // connector/status output immediately on logout so a different account can never
  // see stale connector names while its first refresh is still in flight.
  ['connector-list','connector-jobs','connector-capability','connector-editor-status','connector-transfer-status'].forEach((id) => {
    const node = $(id); if (node) { node.textContent = ''; node.className = id === 'connector-capability' ? 'muted sm' : node.className; }
  });
  const configError = $('config-error'); if (configError) { configError.textContent = ''; configError.classList.add('hidden'); }
  try { closeWebStorageModal(); } catch (_) {}
  // Dashboard pages are hidden on logout but their generated charts/lists are not
  // rebuilt until the next network response. Clear output-only containers so a
  // newly signed-in account can never reveal the previous account while offline.
  document.querySelectorAll('#dashboards-page .chart-body, #dashboards-page .dash-kpis, #dashboards-page .dashboard-alerts, #dashboards-page .dashboard-comparison, #dashboards-page .dashboard-users, #dashboards-page .dashboard-duplicates, #dashboards-page .dashboard-optimization, #dashboards-page .dash-live-list, #dashboards-page .dash-stalled-list, #dashboards-page .dash-summary-grid, #dashboards-page .dash-errors, #dashboards-page .dash-mini-body, #dashboards-page .imgdash-list').forEach((node) => { node.textContent = ''; });
  ['dash-updated','dash-live-updated','dash-filter-summary','dash-alert-count','dash-stalled-count','idash-updated','idash-filter-summary','idash-alert-count'].forEach((id) => { const node = $(id); if (node) node.textContent = ''; });
  try { if (window.DirectXferServerHealth && typeof window.DirectXferServerHealth.clear === 'function') window.DirectXferServerHealth.clear(); } catch (_) {}
}
function showLogin() {
  state.authEpoch += 1;
  state.csrf = null;
  state.username = null;
  state.role = null;
  stopPolling();
  stopNotificationsPolling();
  stopDashboardAutoRefresh();
  closeUserMenu();
  clearAuthenticatedClientState();
  try {
    accountNotifications = [];
    const categoryFilter = $('notifications-category-filter'), severityFilter = $('notifications-severity-filter'), searchFilter = $('notifications-search');
    if (categoryFilter) categoryFilter.value = '';
    if (severityFilter) severityFilter.value = '';
    if (searchFilter) searchFilter.value = '';
    renderNotifications(); closeNotificationsMenu();
  } catch (_) {}
  placeUserMenu('admin');
  ['images-page', 'dashboards-page', 'system-health-page', 'activity-page', 'config-page', 'notifications-page'].forEach((id) => {
    const page = $(id);
    if (page) page.classList.add('hidden');
  });
  $('app-view').classList.add('hidden');
  $('login-view').classList.remove('hidden');
  showTotpRow(false);
  $('login-error').classList.add('hidden');
  hydrateRememberedAdminLogin().finally(() => {
    (($('remember-password').checked && $('password').value) ? $('password') : $('username')).focus();
  });
}
function showApp() {
  $('login-view').classList.add('hidden');
  ['images-page', 'dashboards-page', 'system-health-page', 'activity-page', 'config-page', 'notifications-page'].forEach((id) => {
    const page = $(id);
    if (page) page.classList.add('hidden');
  });
  placeUserMenu('admin');
  $('app-view').classList.remove('hidden');
  applyRole(state.role);
  maybeRedirectNext();
}

// After sign-in, honor a ?next= return path set by the /app gate — but only for
// same-origin /app paths (defends against open-redirects / protocol-relative URLs).
function maybeRedirectNext() {
  try {
    const next = new URLSearchParams(location.search).get('next');
    if (!next) return;
    const target = new URL(next, location.origin);
    if (target.origin !== location.origin || (target.pathname !== '/app/' && target.pathname !== '/app')) return;
    const clean = new URLSearchParams();
    const shared = target.searchParams.get('shared');
    if (shared && /^[A-Za-z0-9_-]{1,160}$/.test(shared)) clean.set('shared', shared);
    const action = target.searchParams.get('action');
    if (action && ['shares','activity','voice-search','widget','system-health','images','settings'].includes(action)) clean.set('action', action);
    const focus = target.searchParams.get('focus');
    if (focus && /^[A-Za-z0-9_-]{1,240}$/.test(focus)) clean.set('focus', focus);
    const dest = target.searchParams.get('dest');
    if (dest && dest.length <= 2048) clean.set('dest', dest);
    const panel = target.searchParams.get('panel');
    if (panel && /^[A-Za-z0-9_-]{1,80}$/.test(panel)) clean.set('panel', panel);
    if (target.searchParams.get('opencenter') === '1') clean.set('opencenter', '1');
    if (target.searchParams.get('paired') === '1') clean.set('paired', '1');
    const query = clean.toString();
    try {
      if (query) sessionStorage.setItem('dx-pwa-post-login-query', '?' + query);
      else sessionStorage.removeItem('dx-pwa-post-login-query');
    } catch (_) {}
    location.replace('/app/');
  } catch (_) {}
}

// Shows/hides owner-only controls and refreshes the current username label.
// Kept separate from applyRole(role) so the two responsibilities cannot
// overwrite each other through duplicate JavaScript function declarations.
function applySessionIdentity() {
  const isOwner = state.role === 'owner';
  const accBtn = $('accounts-btn');
  if (accBtn) accBtn.classList.toggle('hidden', !isOwner);
  document.querySelectorAll('.current-username').forEach((e) => { e.textContent = state.username || ''; });
}

