function showTotpRow(show) {
  $('login-totp-row').classList.toggle('hidden', !show);
  if (!show) $('login-totp').value = '';
}

function passkeyB64uToBytes(value) {
  const text = String(value || '').replace(/-/g, '+').replace(/_/g, '/');
  const padded = text + '='.repeat((4 - (text.length % 4)) % 4);
  const raw = atob(padded);
  return Uint8Array.from(raw, (ch) => ch.charCodeAt(0));
}
function passkeyBytesToB64u(value) {
  const bytes = new Uint8Array(value || new ArrayBuffer(0));
  let raw = '';
  for (const byte of bytes) raw += String.fromCharCode(byte);
  return btoa(raw).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}
function passkeyRequestOptions(publicKey) {
  const options = { ...(publicKey || {}) };
  options.challenge = passkeyB64uToBytes(options.challenge);
  options.allowCredentials = (options.allowCredentials || []).map((row) => ({ ...row, id:passkeyB64uToBytes(row.id) }));
  return options;
}
async function reauthenticateWithPasskey() {
  if (!window.isSecureContext || !window.PublicKeyCredential || !navigator.credentials) return false;
  try {
    const username = String(state.username || (($('username') && $('username').value) || '')).trim();
    const optionRes = await fetchWithTimeout('/app/webauthn/login/options', {
      method:'POST', headers:{ 'Content-Type':'application/json' }, credentials:'same-origin',
      body:JSON.stringify({ username }),
    }, 15000);
    const optionData = await optionRes.json().catch(() => ({}));
    if (!optionRes.ok || !optionData.publicKey || !optionData.token) return false;
    const credential = await navigator.credentials.get({ publicKey:passkeyRequestOptions(optionData.publicKey) });
    if (!credential) return false;
    const response = credential.response || {};
    const verifyRes = await fetchWithTimeout('/app/webauthn/login/verify', {
      method:'POST', headers:{ 'Content-Type':'application/json' }, credentials:'same-origin',
      body:JSON.stringify({
        token:optionData.token,
        deviceName:'Direct-Xfer web',
        credential:{
          id:credential.id,
          rawId:passkeyBytesToB64u(credential.rawId),
          type:credential.type,
          response:{
            clientDataJSON:passkeyBytesToB64u(response.clientDataJSON),
            authenticatorData:passkeyBytesToB64u(response.authenticatorData),
            signature:passkeyBytesToB64u(response.signature),
            userHandle:response.userHandle ? passkeyBytesToB64u(response.userHandle) : null,
          },
        },
      }),
    }, 20000);
    const data = await verifyRes.json().catch(() => ({}));
    if (!verifyRes.ok || !data.csrf) return false;
    state.authEpoch += 1;
    state.csrf = data.csrf;
    state.username = data.username || state.username;
    state.role = data.role || state.role;
    return true;
  } catch (_) {
    return false;
  }
}

async function loginWithPasskey() {
  const errEl = $('login-error');
  errEl.classList.add('hidden');
  if (!window.isSecureContext || !window.PublicKeyCredential || !navigator.credentials) {
    errEl.textContent = t('login.passkeyUnsupported');
    errEl.classList.remove('hidden');
    return;
  }
  const button = $('passkey-login-btn');
  if (button) button.disabled = true;
  try {
    const username = $('username').value.trim();
    const optionRes = await fetchWithTimeout('/app/webauthn/login/options', {
      method:'POST', headers:{ 'Content-Type':'application/json' }, credentials:'same-origin',
      body:JSON.stringify({ username }),
    }, 15000);
    const optionData = await optionRes.json().catch(() => ({}));
    if (!optionRes.ok || !optionData.publicKey || !optionData.token) throw new Error('options');
    const credential = await navigator.credentials.get({ publicKey:passkeyRequestOptions(optionData.publicKey) });
    if (!credential) throw new Error('credential');
    const response = credential.response || {};
    const verifyRes = await fetchWithTimeout('/app/webauthn/login/verify', {
      method:'POST', headers:{ 'Content-Type':'application/json' }, credentials:'same-origin',
      body:JSON.stringify({
        token:optionData.token,
        deviceName:'Direct-Xfer web',
        credential:{
          id:credential.id,
          rawId:passkeyBytesToB64u(credential.rawId),
          type:credential.type,
          response:{
            clientDataJSON:passkeyBytesToB64u(response.clientDataJSON),
            authenticatorData:passkeyBytesToB64u(response.authenticatorData),
            signature:passkeyBytesToB64u(response.signature),
            userHandle:response.userHandle ? passkeyBytesToB64u(response.userHandle) : null,
          },
        },
      }),
    }, 20000);
    const data = await verifyRes.json().catch(() => ({}));
    if (!verifyRes.ok || !data.csrf) throw new Error(data.error || 'verify');
    state.authEpoch += 1;
    state.csrf = data.csrf;
    state.username = data.username;
    state.role = data.role;
    $('password').value = '';
    showTotpRow(false);
    await settleWithin(persistRememberedAdminLogin(data.username || username, '', false), 1200);
    enterApp(data.mustChangePassword);
  } catch (error) {
    if (error && error.name === 'NotAllowedError') errEl.textContent = t('login.passkeyFailed');
    else errEl.textContent = t('login.passkeyFailed');
    errEl.classList.remove('hidden');
  } finally {
    if (button) button.disabled = false;
  }
}

if ($('passkey-login-btn')) $('passkey-login-btn').addEventListener('click', loginWithPasskey);

$('remember-password').addEventListener('change', async () => {
  const checked = $('remember-password').checked;
  loginStorageSet(LOGIN_MEMORY_KEYS.rememberPassword, checked ? '1' : '0');
  if (checked) {
    $('remember-username').checked = true;
    loginStorageSet(LOGIN_MEMORY_KEYS.rememberUsername, '1');
  } else {
    if (window.DXLoginVault) { try { await window.DXLoginVault.clear(); } catch (_) {} }
    lockAdminPasswordField();
  }
});
$('remember-username').addEventListener('change', async () => {
  const checked = $('remember-username').checked;
  loginStorageSet(LOGIN_MEMORY_KEYS.rememberUsername, checked ? '1' : '0');
  if (!checked) {
    $('remember-password').checked = false;
    loginStorageSet(LOGIN_MEMORY_KEYS.rememberPassword, '0');
    loginStorageRemove(LOGIN_MEMORY_KEYS.username);
    loginStorageRemove('dxuser');
    if (window.DXLoginVault) { try { await window.DXLoginVault.clear(); } catch (_) {} }
    lockAdminPasswordField();
  }
});

['pointerdown', 'touchstart', 'focus', 'keydown'].forEach((eventName) => {
  $('password').addEventListener(eventName, unlockAdminPasswordField, { passive: eventName !== 'keydown' });
});

$('login-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const errEl = $('login-error');
  errEl.classList.add('hidden');
  const username = $('username').value.trim();
  unlockAdminPasswordField();
  const password = $('password').value;
  const totp = $('login-totp').value.trim();
  const body = { username, password };
  if (totp) body.totp = totp;
  try {
    const res = await fetchWithTimeout('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify(body),
    }, 15000);
    const data = await res.json().catch(() => ({}));
    if (res.ok && data.csrf) {
      state.authEpoch += 1;
      state.csrf = data.csrf;
      state.username = data.username;
      state.role = data.role;
      await settleWithin(persistRememberedAdminLogin(username, password, !data.mustChangePassword), 1800);
      $('password').value = '';
      showTotpRow(false);
      enterApp(data.mustChangePassword);
    } else if (res.status === 429) {
      errEl.textContent = t('login.tooMany', { s: data.retryAfter || 60 });
      errEl.classList.remove('hidden');
    } else if (data.error === 'passkey-required') {
      showTotpRow(false);
      errEl.textContent = t('login.passkeyRequired');
      errEl.classList.remove('hidden');
      if ($('passkey-login-btn')) $('passkey-login-btn').focus();
    } else if (data.error === 'totp-required') {
      // Password is correct; ask for the 2FA code and keep it entered.
      showTotpRow(true);
      $('login-totp').focus();
    } else if (data.error === 'invalid-totp') {
      showTotpRow(true);
      errEl.textContent = t('login.totpInvalid');
      errEl.classList.remove('hidden');
      $('login-totp').focus();
    } else {
      showTotpRow(false);
      // Base message + any server-provided diagnostic hints (config-based, so they
      // reveal nothing about which usernames exist). Built with textContent/DOM
      // nodes — no HTML injection possible.
      errEl.textContent = t('login.invalid');
      const hints = Array.isArray(data.hints) ? data.hints : [];
      for (const h of hints) {
        const key = 'login.hint.' + h;
        const msg = t(key);
        if (!msg || msg === key) continue; // unknown code: skip
        const div = document.createElement('div');
        div.textContent = msg;
        div.style.cssText = 'margin-top:6px;font-size:.85em;opacity:.85;line-height:1.35';
        errEl.appendChild(div);
      }
      errEl.classList.remove('hidden');
    }
  } catch (_) {
    errEl.textContent = t('login.connError');
    errEl.classList.remove('hidden');
  }
});

$('logout-btn').addEventListener('click', async () => {
  // Invalidate all older dashboard/API responses before the logout request starts.
  state.authEpoch += 1;
  try {
    await api('POST', '/api/logout');
  } catch (_) {}
  state.csrf = null;
  accountNotifications = [];
  renderNotifications();
  showLogin();
});

// --- Shut down the server (user menu) ---
$('shutdown-server-btn').addEventListener('click', async () => {
  closeUserMenu();
  if (!confirm(t('menu.shutdownConfirm'))) return;
  try {
    // The server answers before it actually closes, so this request succeeds.
    await api('POST', '/api/shutdown');
    stopPolling();
    toast(t('menu.shutdownDone'), 'warn');
    state.connLost = true;
    showBanner(t('sh.connLost'));
  } catch (e) {
    if (e.message !== 'not-authenticated') toast(t('menu.shutdownFail'), 'err');
  }
});

