function rememberConfiguredStorageRemote(remote) {
  const clean=String(remote||'').trim().replace(/:$/,'');
  if(!clean)return;
  if(!storageConnectorRemotes.includes(clean))storageConnectorRemotes.push(clean);
  const datalist=$('connector-remotes');
  if(datalist){
    datalist.textContent='';
    storageConnectorRemotes.forEach((name)=>datalist.appendChild(el('option',{attrs:{value:name}})));
  }
  connectorInitialLoadFailures=0;
  const cap=$('connector-capability');
  if(cap){cap.textContent=t('connector.remoteConfiguredReady');cap.className='sm cfg-ok';}
}
function renderStorageConnectors(data) {
  storageConnectors = Array.isArray(data && data.connectors) ? data.connectors : [];
  const returnedRemotes = Array.isArray(data && data.remotes) ? data.remotes.slice() : [];
  const cap = $('connector-capability');
  if (cap) {
    const skipped = !!(data && data.capabilities && data.capabilities.skipped);
    const pending = !!(data && data.capabilities && data.capabilities.pending);
    const available = data && data.capabilities && data.capabilities.available;
    if (!storageConnectors.length && returnedRemotes.length) {
      cap.textContent = t('connector.remoteReadyNoConnector');
      cap.className = 'sm cfg-ok';
    } else if (skipped) {
      cap.textContent = t('connector.noneHint');
      cap.className = 'muted sm';
    } else if (pending) {
      cap.textContent = t('connector.runtimeChecking');
      cap.className = 'muted sm';
    } else {
      cap.textContent = available
        ? t('connector.ready', { version:data.capabilities.version || 'rclone' })
        : t('connector.unavailable');
      cap.className = 'sm ' + (available ? 'cfg-ok' : 'cfg-warn');
    }
  }
  storageConnectorRemotes = returnedRemotes;
  const datalist = $('connector-remotes');
  if (datalist) {
    datalist.textContent = '';
    storageConnectorRemotes.forEach((remote) => datalist.appendChild(el('option', { attrs:{ value:remote } })));
  }
  const remoteField=$('connector-remote');
  if(remoteField&&!remoteField.value.trim()&&storageConnectorRemotes.length===1)remoteField.value=storageConnectorRemotes[0];
  const select = $('connector-transfer-id');
  if (select) {
    const previous = select.value; select.textContent = '';
    storageConnectors.forEach((connector) => select.appendChild(el('option', { attrs:{ value:connector.id }, text:connector.name })));
    if (storageConnectors.some((connector) => connector.id === previous)) select.value = previous;
    updateConnectorTransferActions();
  }
  const list = $('connector-list');
  if (list) {
    list.textContent = '';
    if (!storageConnectors.length) list.appendChild(el('div', { class:'muted sm', text:t('connector.none') }));
    storageConnectors.forEach((connector) => {
      const row = el('div', { class:'connector-row' });
      const main = el('div', { class:'connector-main' });
      main.appendChild(el('strong', { text:connector.name }));
      main.appendChild(el('div', { class:'connector-meta', text:`${connector.type} · ${connector.remote}:${connector.root || ''}${connector.readOnly ? ' · ' + t('connector.readOnlyShort') : ''}` }));
      const actions = el('div', { class:'connector-actions' });
      const testBtn = el('button', { attrs:{ type:'button' }, class:'btn ghost xs', text:t('connector.test') });
      testBtn.addEventListener('click', async () => {
        testBtn.disabled = true; connectorStatus('connector-editor-status', 'connector.testing');
        try { await api('POST', `/api/storage/connectors/${encodeURIComponent(connector.id)}/test`, {}, 60000); connectorStatus('connector-editor-status', 'connector.testOk'); }
        catch (_) { connectorStatus('connector-editor-status', 'connector.testFail', true); }
        finally { testBtn.disabled = false; }
      });
      const editBtn = el('button', { attrs:{ type:'button' }, class:'btn ghost xs', text:t('connector.edit') });
      editBtn.addEventListener('click', () => {
        connectorEditingId = connector.id;
        $('connector-name').value = connector.name; $('connector-type').value = connector.type;
        $('connector-remote').value = connector.remote; $('connector-root').value = connector.root || '';
        $('connector-readonly').checked = !!connector.readOnly; $('connector-add').textContent = t('connector.save');
      });
      const delBtn = el('button', { attrs:{ type:'button' }, class:'btn danger xs', text:t('connector.delete') });
      delBtn.addEventListener('click', async () => {
        if (!confirm(t('connector.deleteConfirm', { name:connector.name }))) return;
        delBtn.disabled = true;
        try { await api('DELETE', `/api/storage/connectors/${encodeURIComponent(connector.id)}`); if (connectorEditingId === connector.id) resetConnectorEditor(); await refreshStorageConnectors(); }
        catch (_) { delBtn.disabled = false; connectorStatus('connector-editor-status', 'connector.deleteFail', true); }
      });
      actions.append(testBtn, editBtn, delBtn); row.append(main, actions); list.appendChild(row);
    });
  }
  const connectorJobs = Array.isArray(data && data.jobs) ? data.jobs : [];
  const jobs = $('connector-jobs');
  if (jobs) {
    jobs.textContent = '';
    connectorJobs.slice(0, 25).forEach((job) => {
      const row = el('div', { class:`connector-job is-${job.status || 'queued'}` });
      const main = el('div', { class:'connector-main' });
      main.appendChild(el('strong', { text:`${job.direction === 'import' ? '↓' : '↑'} ${job.sourceName || '?'} → ${job.targetName || '?'}` }));
      main.appendChild(el('div', { class:'connector-meta', text:`${job.connectorName || ''} · ${t('connector.status.' + (job.status || 'queued'))}${job.error ? ' · ' + job.error : ''}` }));
      row.appendChild(main);
      if (['queued','running'].includes(job.status)) {
        const cancel = el('button', { attrs:{ type:'button' }, class:'btn danger xs', text:t('connector.cancel') });
        cancel.addEventListener('click', async () => { cancel.disabled = true; try { await api('POST', `/api/storage/jobs/${encodeURIComponent(job.id)}/cancel`, {}); } catch (_) { cancel.disabled = false; } });
        row.appendChild(cancel);
      }
      jobs.appendChild(row);
    });
  }
  if (connectorRefreshTimer) { clearTimeout(connectorRefreshTimer); connectorRefreshTimer = null; }
  if (connectorJobs.some((job) => job && ['queued','running'].includes(job.status)) && configPageOpen()) {
    connectorRefreshTimer = setTimeout(() => { connectorRefreshTimer = null; void refreshStorageConnectors(); }, 2500);
  }
}
async function refreshStorageConnectors(forceProbe) {
  const refreshSerial = ++connectorRefreshSerial;
  if(!googleOAuthProfileState.loaded)void refreshGoogleOAuthProfileStatus();
  // The Configuration page must never treat a first-use/empty connector state as
  // an error. The summary endpoint is only an optimization: if it is unavailable
  // (for example during an upgrade where browser assets and ServerHost briefly differ),
  // fall back to the canonical connector endpoint before surfacing any error.
  if (connectorInitialLoadRetryTimer) { clearTimeout(connectorInitialLoadRetryTimer); connectorInitialLoadRetryTimer = null; }
  // Keep the lightweight summary preflight for a fast neutral first paint, but do
  // not return early when it reports zero Direct-Xfer connector records. A configured
  // rclone remote can already exist at that point (notably just after Google OAuth),
  // so the canonical endpoint still has to run and restore the remote list.
  if (!forceProbe) {
    try {
      const summary = await api('GET', '/api/storage/connectors/summary', null, 10000);
      const configured = Math.max(0, Number(summary && summary.configured) || 0);
      if (!configured && !forceProbe && storageConnectors.length === 0 && refreshSerial === connectorRefreshSerial) {
        connectorInitialLoadFailures = 0;
        // Summary is advisory only. Never let it clear the rendered connector list;
        // the canonical endpoint below is the sole source of truth for inventory.
      }
    } catch (_) {
      // Deliberately silent. The canonical connector endpoint below remains the
      // source of truth and now has a bounded rclone probe.
    }
  }
  try {
    const data = await api('GET', '/api/storage/connectors', null, 30000);
    if (refreshSerial !== connectorRefreshSerial) return;
    connectorInitialLoadFailures = 0;
    connectorInventoryConfirmed = true;
    const connectors = Array.isArray(data && data.connectors) ? data.connectors : [];
    if (!connectors.length && !forceProbe) {
      const remotes=Array.isArray(data&&data.remotes)?data.remotes:[];
      renderStorageConnectors({ ...data, connectors:[], capabilities:{ ...(data && data.capabilities || {}), skipped:!remotes.length } });
      return;
    }
    renderStorageConnectors(data);
  } catch (error) {
    if (refreshSerial !== connectorRefreshSerial) return;
    // On the automatic first load, avoid a scary red banner before the user has
    // configured anything. Keep the UI usable, retry once silently, and reserve the
    // red diagnostic for an explicit refresh or for a previously loaded connector set.
    if (!forceProbe && storageConnectors.length === 0) {
      connectorInitialLoadFailures += 1;
      renderStorageConnectors({ connectors:[], jobs:[], capabilities:{ skipped:true }, remotes:[], types:[] });
      if (connectorInitialLoadFailures < 2 && configPageOpen()) {
        connectorInitialLoadRetryTimer = setTimeout(() => { connectorInitialLoadRetryTimer = null; void refreshStorageConnectors(false); }, 1200);
      }
      return;
    }
    // Preserve the last server-confirmed connector snapshot on transient read
    // failures. Once inventory has been confirmed, a background refresh failure is
    // not an inventory-load failure and must never replace a valid connector list
    // with the scary red "Could not load connectors" banner. Keep the last
    // capability state intact; an explicit refresh with no confirmed snapshot may
    // still surface the diagnostic below.
    updateConnectorTransferActions();
    if (!connectorInventoryConfirmed && storageConnectors.length === 0) {
      connectorStatus('connector-capability', 'connector.loadFail', true);
    }
  }
}
if ($('connector-add')) $('connector-add').addEventListener('click', async () => {
  const payload = connectorPayload();
  if (!payload.name || !payload.remote) return connectorStatus('connector-editor-status', 'connector.required', true);
  $('connector-add').disabled = true;
  try {
    const result = connectorEditingId
      ? await api('PATCH', `/api/storage/connectors/${encodeURIComponent(connectorEditingId)}`, payload)
      : await api('POST', '/api/storage/connectors', payload);
    const saved = result && result.connector;
    const authoritative = Array.isArray(result && result.connectors) ? result.connectors : null;
    if (authoritative || (saved && saved.id)) connectorInventoryConfirmed = true;
    if (authoritative) {
      renderStorageConnectors({ connectors:authoritative, jobs:[], capabilities:{ pending:true }, remotes:storageConnectorRemotes.slice(), types:[] });
    } else if (saved && saved.id) {
      const next = storageConnectors.filter((item) => item && item.id !== saved.id);
      next.push(saved);
      renderStorageConnectors({ connectors:next, jobs:[], capabilities:{ pending:true }, remotes:storageConnectorRemotes.slice(), types:[] });
    }
    // Invalidate any older in-flight connector reads before a post-save refresh.
    connectorRefreshSerial += 1;
    resetConnectorEditor(); connectorStatus('connector-editor-status', 'connector.saved');
    void refreshStorageConnectors(false);
  } catch (_) { connectorStatus('connector-editor-status', 'connector.saveFail', true); }
  finally { $('connector-add').disabled = false; }
});
async function startConnectorTransfer(direction) {
  const id = $('connector-transfer-id').value;
  const remotePath = $('connector-remote-path').value.trim();
  const localPath = $('connector-local-path').value.trim();
  if (!id || !remotePath || (direction === 'export' && !localPath)) return connectorStatus('connector-transfer-status', 'connector.required', true);
  const body = direction === 'import' ? { remotePath, target:localPath } : { source:localPath, remotePath };
  try {
    await api('POST', `/api/storage/connectors/${encodeURIComponent(id)}/${direction}`, body);
    connectorStatus('connector-transfer-status', 'connector.queued'); await refreshStorageConnectors();
  } catch (_) { connectorStatus('connector-transfer-status', 'connector.transferFail', true); }
}
if ($('connector-import')) $('connector-import').addEventListener('click', () => startConnectorTransfer('import'));
if ($('connector-export')) $('connector-export').addEventListener('click', () => startConnectorTransfer('export'));
if ($('connector-transfer-id')) $('connector-transfer-id').addEventListener('change', updateConnectorTransferActions);
if ($('connector-refresh')) $('connector-refresh').addEventListener('click', () => refreshStorageConnectors(true));

// Web-storage links ---------------------------------------------------------
// A web-storage link freezes the selected connector route server-side. Read-only
// links stream downloads through rclone; reception/collaboration links stage each
// upload temporarily for resumability/security checks, then publish it remotely.
let webStorageMode = 'share';
let webStoragePath = '';
let webStorageSelectedPath = null;
let webStorageSelectedIsDir = false;
let webStorageLoadSerial = 0;
function closeWebStorageModal() {
  const overlay = $('web-storage-overlay'); if (!overlay) return;
  overlay.classList.add('hidden');
  webStorageLoadSerial++;
  webStorageMode='share';
  webStorageSelectedPath = null; webStorageSelectedIsDir = false; webStoragePath = '';
  if ($('web-storage-connector')) $('web-storage-connector').replaceChildren();
  if ($('web-storage-list')) $('web-storage-list').replaceChildren();
  if ($('web-storage-path')) $('web-storage-path').textContent='/';
  if ($('web-storage-selection')) $('web-storage-selection').textContent='—';
  for (const id of ['web-storage-password','web-storage-name','web-storage-note','web-storage-maxdl','web-storage-rate','web-storage-maxfiles','web-storage-maxfiles-upload','web-storage-maxfile','web-storage-maxtotal','web-storage-maxfiles-sender','web-storage-maxmb-sender','web-storage-allow','web-storage-block']) if ($(id)) $(id).value='';
  for (const id of ['web-storage-preview','web-storage-burn','web-storage-block-exec','web-storage-group-sender','web-storage-tag-sender','web-storage-require-sender','web-storage-allow-delete']) if ($(id)) $(id).checked=false;
  if ($('web-storage-preview')) $('web-storage-preview').checked=true;
  if ($('web-storage-write-options')) $('web-storage-write-options').classList.add('hidden');
  if ($('web-storage-collab-delete-row')) $('web-storage-collab-delete-row').classList.add('hidden');
  if ($('web-storage-inbox-group-row')) $('web-storage-inbox-group-row').classList.remove('hidden');
  if ($('web-storage-inbox-tag-row')) $('web-storage-inbox-tag-row').classList.remove('hidden');
  if ($('web-storage-inbox-sender-limits')) $('web-storage-inbox-sender-limits').classList.remove('hidden');
  if ($('web-storage-inbox-require-row')) $('web-storage-inbox-require-row').classList.remove('hidden');
  document.querySelectorAll('.web-storage-download-only').forEach((node)=>node.classList.remove('hidden'));
  if ($('web-storage-new-folder')) $('web-storage-new-folder').classList.add('hidden');
  webStorageShowNewFolder(false);
  if ($('web-storage-error')) { $('web-storage-error').textContent=''; $('web-storage-error').classList.add('hidden'); }
}
function webStorageSetError(message) {
  const node=$('web-storage-error'); if(!node)return;
  node.textContent=message||''; node.classList.toggle('hidden', !message);
}
function webStorageShowNewFolder(show) {
  const row=$('web-storage-new-folder-row'), input=$('web-storage-new-folder-name');
  if(row) row.classList.toggle('hidden', !show);
  if(!show && input) input.value='';
  if(show && input) { input.value=''; input.focus(); input.select(); }
}
function webStorageFolderErrorMessage(error) {
  const code=String(error && error.data && error.data.error || error && error.message || '').trim();
  if(code==='folder-exists') return t('webStorage.folderExists');
  if(code==='invalid-folder-name'||code==='invalid-remote-path') return t('webStorage.folderInvalid');
  if(code==='read-only') return t('webStorage.folderReadOnly');
  if(code.startsWith('connector-')||code==='rclone-unavailable'||code==='remote-not-found'||code==='not-found') return webStorageBrowseErrorMessage(error,'browse');
  return t('webStorage.folderCreateFail');
}
function webStorageSetSelection(path, isDir, name) {
  webStorageSelectedPath = path == null ? null : String(path);
  webStorageSelectedIsDir = !!isDir;
  const label=$('web-storage-selection');
  if (label) label.textContent = webStorageSelectedPath == null ? '—' : (name || webStorageSelectedPath || '/');
  const create=$('web-storage-create'); if(create) create.disabled = webStorageSelectedPath == null || (webStorageMode!=='share' && !webStorageSelectedIsDir);
  const list=$('web-storage-list');
  if (list) Array.from(list.querySelectorAll('.web-storage-row')).forEach((row)=>row.classList.toggle('is-selected', row.dataset.path === webStorageSelectedPath));
}
function webStorageParentPath(value) {
  const parts=String(value||'').split('/').filter(Boolean); parts.pop(); return parts.join('/');
}
const WEB_STORAGE_NOTICE_MS = 10000;
function webStorageToast(message, kind='err') {
  if (message) toast(message, kind, WEB_STORAGE_NOTICE_MS);
}
function webStorageBrowseErrorMessage(error, context='browse') {
  const code=String(error && error.data && error.data.error || error && error.message || '').trim();
  if(code==='rclone-unavailable') return t('webStorage.rcloneMissing');
  if(code==='connector-not-found'||code==='not-found') return t('webStorage.connectorMissing');
  if(code==='remote-not-found') return t('webStorage.remoteMissing');
  if(code==='connector-auth-failed'||code==='connector-token-invalid') return t('webStorage.authFailed');
  if(code==='connector-tls-ca-untrusted') return t('webStorage.tlsCaUntrusted');
  if(code==='connector-api-disabled') return t('webStorage.apiDisabled');
  if(code==='connector-config-storage') return t('webStorage.configStorage');
  if(code==='connector-forbidden') return t('webStorage.providerForbidden');
  if(code==='connector-unreachable') return t('webStorage.providerUnavailable');
  if(code==='connector-rate-limited') return t('webStorage.providerRateLimited');
  if(code==='connector-timeout') return t('webStorage.providerTimeout');
  if(code==='connector-response') return t('webStorage.invalidResponse');
  if(code==='connector-cancelled'||code==='connector-terminated') return t('webStorage.browseInterrupted');
  if(code==='fetch-timeout') return t('webStorage.requestTimeout');
  if(code==='not-authenticated'||code==='stale-auth') return '';
  if(context==='connectors'||context==='connector-summary') {
    if(error && error.status===403) return t('webStorage.connectorForbidden');
    if(error && error.status===404) return t('webStorage.connectorApiMissing');
    return t(context==='connector-summary'?'webStorage.connectorCheckFail':'webStorage.connectorListFail');
  }
  if(code==='connector-failed') return t('webStorage.connectorGeneric');
  return t('webStorage.loadFail');
}
async function loadWebStoragePath(pathValue) {
  const connectorId=$('web-storage-connector') && $('web-storage-connector').value;
  if (!connectorId) return;
  const serial=++webStorageLoadSerial;
  const clean=String(pathValue||'').replace(/^\/+|\/+$/g,'');
  const list=$('web-storage-list');
  if(list) list.replaceChildren(el('div',{class:'muted sm',text:'…'}));
  webStorageSetError('');
  try {
    const data=await api('GET', `/api/storage/connectors/${encodeURIComponent(connectorId)}/list?path=${encodeURIComponent(clean)}`, null, 60000);
    if (serial !== webStorageLoadSerial) return;
    webStoragePath=String(data && data.path || clean || '');
    if($('web-storage-path')) $('web-storage-path').textContent='/' + webStoragePath;
    if($('web-storage-up')) $('web-storage-up').disabled=!webStoragePath;
    if(list) list.textContent='';
    const entries=Array.isArray(data && data.entries)?data.entries:[];
    if(!entries.length && list) list.appendChild(el('div',{class:'muted sm',text:t('webStorage.empty')}));
    entries.forEach((entry)=>{
      if(!entry || !entry.path) return;
      const row=el('button',{class:'web-storage-row',attrs:{type:'button'}});
      row.dataset.path=entry.path;
      row.appendChild(el('span',{text:entry.isDir?'📁':'☁'}));
      row.appendChild(el('span',{class:'web-storage-row-name',text:entry.name||entry.path}));
      row.appendChild(el('span',{class:'web-storage-row-size muted sm',text:entry.isDir?'—':formatBytes(entry.size||0)}));
      row.addEventListener('click',()=>{
        if(entry.isDir) { webStorageSetSelection(null,false); void loadWebStoragePath(entry.path); }
        else if(webStorageMode==='share') webStorageSetSelection(entry.path,false,entry.name);
      });
      if(list) list.appendChild(row);
    });
  } catch (error) {
    if(serial!==webStorageLoadSerial)return;
    if(list) list.textContent='';
    webStorageSetError(webStorageBrowseErrorMessage(error,'browse'));
  }
}
async function openWebStorageModal(mode='share') {
  webStorageMode=['inbox','collab'].includes(mode)?mode:'share';
  const overlay=$('web-storage-overlay'); if(!overlay)return;
  webStorageSetError(''); webStorageSetSelection(null,false); webStoragePath='';
  const writable=webStorageMode!=='share';
  if($('web-storage-new-folder')) $('web-storage-new-folder').classList.toggle('hidden', !writable);
  webStorageShowNewFolder(false);
  const title=$('web-storage-title');
  if(title) title.textContent=t(webStorageMode==='inbox'?'webStorage.inboxTitle':webStorageMode==='collab'?'webStorage.collabTitle':'webStorage.title');
  const hint=$('web-storage-hint');
  if(hint) hint.textContent=t(writable?'webStorage.writeHint':'webStorage.directHint');
  document.querySelectorAll('.web-storage-download-only').forEach((node)=>node.classList.toggle('hidden',writable));
  if($('web-storage-write-options')) $('web-storage-write-options').classList.toggle('hidden',!writable);
  if($('web-storage-collab-delete-row')) $('web-storage-collab-delete-row').classList.toggle('hidden',webStorageMode!=='collab');
  if($('web-storage-inbox-group-row')) $('web-storage-inbox-group-row').classList.toggle('hidden',webStorageMode!=='inbox');
  if($('web-storage-inbox-tag-row')) $('web-storage-inbox-tag-row').classList.toggle('hidden',webStorageMode!=='inbox');
  if($('web-storage-inbox-sender-limits')) $('web-storage-inbox-sender-limits').classList.toggle('hidden',webStorageMode!=='inbox');
  if($('web-storage-inbox-require-row')) $('web-storage-inbox-require-row').classList.toggle('hidden',webStorageMode!=='inbox');
  try {
    // Check connector metadata first without probing rclone. This makes the
    // common first-use case deterministic: no configured storage is reported as
    // such, rather than being masked by an optional-runtime/probe failure.
    let summary;
    try { summary=await api('GET','/api/storage/connectors/summary',null,10000); }
    catch (error) {
      const message=webStorageBrowseErrorMessage(error,'connector-summary');
      if(message) webStorageToast(message,'err');
      return;
    }
    const configured=Math.max(0, Number(summary && summary.configured) || 0);
    const writableConfigured=Math.max(0, Number(summary && summary.writable) || 0);
    if(!configured) { webStorageToast(t('webStorage.none'),'warn'); return; }
    if(writable && !writableConfigured) { webStorageToast(t('webStorage.noneWritable'),'warn'); return; }

    const data=await api('GET','/api/storage/connectors',null,30000);
    const capabilities=data && data.capabilities || {};
    const available=!!capabilities.available, pending=!!capabilities.pending;
    let connectors=Array.isArray(data && data.connectors)?data.connectors:[];
    if(writable) connectors=connectors.filter((connector)=>connector && !connector.readOnly);
    // Missing connector configuration is the first actionable condition. This is
    // more precise than reporting the optional rclone runtime when nothing has
    // been configured yet.
    if(!connectors.length) { webStorageToast(t(writable?'webStorage.noneWritable':'webStorage.none'),'warn'); return; }
    // A bounded configuration probe may still be running. Do not reject a
    // confirmed connector merely because that optional probe timed out; the real
    // browse request below is authoritative and will return a precise rclone error.
    if(!available && !pending) { webStorageToast(t('webStorage.rcloneMissing'),'err'); return; }
    const select=$('web-storage-connector'); select.textContent='';
    connectors.forEach((connector)=>select.appendChild(el('option',{attrs:{value:connector.id},text:connector.name})));
    const settings=state.settings||{};
    const forceNever=settings.newSharesNeverExpire===true;
    if($('web-storage-expiry')) $('web-storage-expiry').value=forceNever?'0':String(settings.defaultExpiry||0);
    if($('web-storage-password')) { $('web-storage-password').value=''; $('web-storage-password').required=!!settings.defaultRequirePassword; }
    for(const id of ['web-storage-maxdl','web-storage-rate','web-storage-maxfiles','web-storage-maxfiles-upload','web-storage-maxfile','web-storage-maxtotal','web-storage-maxfiles-sender','web-storage-maxmb-sender','web-storage-allow','web-storage-block','web-storage-name','web-storage-note']) if($(id)) $(id).value='';
    if($('web-storage-preview')) $('web-storage-preview').checked=settings.defaultAllowPreview!==false;
    if($('web-storage-burn')) $('web-storage-burn').checked=!!settings.defaultBurnAfterDownload;
    for(const id of ['web-storage-block-exec','web-storage-group-sender','web-storage-require-sender','web-storage-allow-delete']) if($(id)) $(id).checked=false;
    overlay.classList.remove('hidden');
    if (select) select.focus();
    await loadWebStoragePath('');
  } catch (error) {
    const message=webStorageBrowseErrorMessage(error,'connectors');
    if(message) webStorageToast(message,'err');
  }
}
if($('new-web-storage-btn')) $('new-web-storage-btn').addEventListener('click',()=>openWebStorageModal('share'));
if($('new-web-inbox-btn')) $('new-web-inbox-btn').addEventListener('click',()=>openWebStorageModal('inbox'));
if($('new-web-collab-btn')) $('new-web-collab-btn').addEventListener('click',()=>openWebStorageModal('collab'));
if($('web-storage-close')) $('web-storage-close').addEventListener('click',closeWebStorageModal);
if($('web-storage-cancel')) $('web-storage-cancel').addEventListener('click',closeWebStorageModal);
if($('web-storage-overlay')) $('web-storage-overlay').addEventListener('click',(e)=>{if(e.target===$('web-storage-overlay'))closeWebStorageModal();});
document.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&$('web-storage-overlay')&&!$('web-storage-overlay').classList.contains('hidden')){e.preventDefault();closeWebStorageModal();}});
if($('web-storage-connector')) $('web-storage-connector').addEventListener('change',()=>{webStorageShowNewFolder(false);webStorageSetSelection(null,false);void loadWebStoragePath('');});
if($('web-storage-up')) $('web-storage-up').addEventListener('click',()=>{webStorageShowNewFolder(false);webStorageSetSelection(null,false);void loadWebStoragePath(webStorageParentPath(webStoragePath));});
if($('web-storage-refresh')) $('web-storage-refresh').addEventListener('click',()=>void loadWebStoragePath(webStoragePath));
if($('web-storage-select-folder')) $('web-storage-select-folder').addEventListener('click',()=>webStorageSetSelection(webStoragePath,true,webStoragePath||'/'));
if($('web-storage-new-folder')) $('web-storage-new-folder').addEventListener('click',()=>{if(webStorageMode!=='share'){webStorageSetError('');webStorageShowNewFolder(true);}});
if($('web-storage-new-folder-cancel')) $('web-storage-new-folder-cancel').addEventListener('click',()=>webStorageShowNewFolder(false));
async function createWebStorageFolder() {
  if(webStorageMode==='share') return;
  const connectorId=$('web-storage-connector') && $('web-storage-connector').value;
  const input=$('web-storage-new-folder-name'), button=$('web-storage-new-folder-create');
  const name=String(input && input.value || '').trim();
  if(!connectorId||!name){webStorageSetError(t('webStorage.folderInvalid'));if(input)input.focus();return;}
  const parentPath=webStoragePath;
  if(button) button.disabled=true;
  webStorageSetError('');
  try {
    const result=await api('POST',`/api/storage/connectors/${encodeURIComponent(connectorId)}/mkdir`,{parentPath,name},60000);
    const createdPath=String(result && result.path || [parentPath,name].filter(Boolean).join('/'));
    const createdName=String(result && result.name || name);
    webStorageShowNewFolder(false);
    await loadWebStoragePath(createdPath);
    webStorageSetSelection(createdPath,true,createdName);
    toast(t('webStorage.folderCreated'),'ok');
  } catch(error) {
    webStorageSetError(webStorageFolderErrorMessage(error));
    if(input){input.focus();input.select();}
  } finally { if(button) button.disabled=false; }
}
if($('web-storage-new-folder-create')) $('web-storage-new-folder-create').addEventListener('click',()=>void createWebStorageFolder());
if($('web-storage-new-folder-name')) $('web-storage-new-folder-name').addEventListener('keydown',(event)=>{
  if(event.key==='Enter'){event.preventDefault();void createWebStorageFolder();}
  else if(event.key==='Escape'){event.preventDefault();event.stopPropagation();webStorageShowNewFolder(false);}
});
if($('web-storage-create')) $('web-storage-create').addEventListener('click',async()=>{
  if(webStorageSelectedPath==null || (webStorageMode!=='share'&&!webStorageSelectedIsDir))return;
  const password=String($('web-storage-password').value||'');
  if($('web-storage-password').required&&!password){toast(t('cfg.pwRequired'),'err');$('web-storage-password').focus();return;}
  if(webStorageMode==='collab' && $('web-storage-allow-delete') && $('web-storage-allow-delete').checked && !password){webStorageSetError(t('webStorage.deleteNeedsPassword'));$('web-storage-password').focus();return;}
  const button=$('web-storage-create'); button.disabled=true; webStorageSetError('');
  const payload={
    connectorId:$('web-storage-connector').value,
    remotePath:webStorageSelectedPath,
    name:String($('web-storage-name').value||'').trim(),
    expiresInSeconds:parseInt($('web-storage-expiry').value,10)||0,
    password,
    note:String($('web-storage-note').value||''),
  };
  let endpoint='/api/shares/web-storage';
  if(webStorageMode==='share'){
    const rateRaw=String($('web-storage-rate').value||'').trim(),rateKBps=rateRaw===''?0:Number(rateRaw);
    if(!Number.isInteger(rateKBps)||rateKBps<0){webStorageSetError(t('sh.addFail',{error:'invalid-rate'}));button.disabled=false;return;}
    Object.assign(payload,{maxDownloads:parseInt($('web-storage-maxdl').value,10)||0,rateKBps,noPreview:!$('web-storage-preview').checked,burnAfterDownload:$('web-storage-burn').checked});
  } else {
    const csv=(id)=>String($(id)&&$(id).value||'').split(',').map((v)=>v.trim()).filter(Boolean);
    Object.assign(payload,{
      maxFiles:parseInt($('web-storage-maxfiles').value,10)||0,
      maxFilesPerUpload:parseInt($('web-storage-maxfiles-upload').value,10)||0,
      maxFileBytes:mbToBytes($('web-storage-maxfile')&&$('web-storage-maxfile').value),
      maxTotalBytes:mbToBytes($('web-storage-maxtotal')&&$('web-storage-maxtotal').value),
      allowExt:csv('web-storage-allow'), blockExt:csv('web-storage-block'),
      blockExecutables:!!($('web-storage-block-exec')&&$('web-storage-block-exec').checked),
    });
    if(webStorageMode==='inbox') Object.assign(payload,{
      maxFilesPerSender:parseInt($('web-storage-maxfiles-sender').value,10)||0,
      maxBytesPerSender:mbToBytes($('web-storage-maxmb-sender').value),
      groupBySender:!!$('web-storage-group-sender').checked,
      tagBySender:!!$('web-storage-tag-sender').checked,
      requireSenderName:!!$('web-storage-require-sender').checked,
    });
    else Object.assign(payload,{allowDelete:!!$('web-storage-allow-delete').checked});
    endpoint=webStorageMode==='inbox'?'/api/inbox/web-storage':'/api/collab/web-storage';
  }
  try {
    const resp=webStorageMode==='inbox'?await api('POST',endpoint,payload):await apiWithDlpOverride('POST',endpoint,payload);
    if(password&&resp&&resp.share)rememberLinkPassword(resp.share.url,password);
    if(resp&&resp.share)showCreatedShareLink(resp.share);
    toast(t(webStorageMode==='inbox'?'webStorage.inboxCreated':webStorageMode==='collab'?'webStorage.collabCreated':'webStorage.created'),'ok');
    closeWebStorageModal(); await refreshShares();
  } catch(error) {
    if (isDlpCancelled(error)) { toast(t('dlp.cancelled'),'warn'); return; }
    const code=String(error&&error.data&&error.data.error||error.message||'error');
    const connectorFailure=code==='rclone-unavailable'||code==='remote-not-found'||code==='connector-not-found'||code.startsWith('connector-');
    webStorageSetError(connectorFailure?webStorageBrowseErrorMessage(error,'browse'):t('webStorage.createFail',{error:code}));
  } finally { if(button && !$('web-storage-overlay').classList.contains('hidden')) button.disabled=webStorageSelectedPath==null||(webStorageMode!=='share'&&!webStorageSelectedIsDir); }
});

// --- Configuration page — dedicated owner/admin full-page view --------------
const CONFIG_PATH = '/configuration';
function configPageOpen() {
  const page = $('config-page');
  return !!page && !page.classList.contains('hidden');
}
function showConfigView() {
  if (!['owner','admin',''].includes(state.role || '')) return false;
  closeUserMenu();
  const notificationsPage = $('notifications-page'); if (notificationsPage) notificationsPage.classList.add('hidden');
  stopDashboardAutoRefresh();
  ['images-page','dashboards-page','system-health-page','activity-page'].forEach((id) => {
    const page = $(id); if (page) page.classList.add('hidden');
  });
  $('app-view').classList.add('hidden');
  placeUserMenu('config');
  $('config-page').classList.remove('hidden');
  document.title = t('app.name') + ' — ' + t('cfg.title');
  void populateConfigPage();
  window.scrollTo(0, 0);
  return true;
}
function hideConfigView(showHome = true) {
  const page = $('config-page'); if (!page) return;
  closeUserMenu();
  page.classList.add('hidden');
  if (connectorRefreshTimer) { clearTimeout(connectorRefreshTimer); connectorRefreshTimer = null; }
  if (showHome) {
    placeUserMenu('admin');
    $('app-view').classList.remove('hidden');
    document.title = t('app.docTitle');
  }
}
function openConfigPage() {
  if (configPageOpen()) { void populateConfigPage(); return; }
  if (!showConfigView()) return;
  try { if (location.pathname !== CONFIG_PATH) history.pushState({ dxView:'config' }, '', CONFIG_PATH); } catch (_) {}
}
function closeConfigPage() {
  if (!configPageOpen()) return;
  if (history.state && history.state.dxView === 'config') history.back();
  else {
    hideConfigView();
    if (location.pathname === CONFIG_PATH) { try { history.replaceState({ dxView:'home' }, '', '/'); } catch (_) {} }
  }
}
// Compatibility names retained for older internal callers and restored historical tests.
function openConfigModal() { openConfigPage(); }
function closeConfigModal() { closeConfigPage(); }
if ($('config-btn')) $('config-btn').addEventListener('click', (e) => {
  e.stopPropagation();
  closeUserMenu();
  closeDashMenu();
  openConfigPage();
});
if ($('config-close')) $('config-close').addEventListener('click', closeConfigPage);
if ($('config-cancel')) $('config-cancel').addEventListener('click', closeConfigPage);
