function pendingShareDeletionFor(id) {
  return !!(state.pendingShareDeletion && state.pendingShareDeletion.id === id);
}

function pendingShareDeletionBar(s) {
  const bar = el('div', { class: 'share-undo', attrs: { role: 'status' } });
  bar.appendChild(el('span', { class: 'share-undo-message', text: t('sh.revokePending') }));
  const undo = el('button', { class: 'btn sm', text: t('sh.undoRevoke') });
  undo.addEventListener('click', () => undoPendingShareDeletion(s.id));
  bar.appendChild(undo);
  return bar;
}

function rerenderShareCollections() {
  state.lastSharesJson = '';
  state.lastPhotosSig = '';
  if (state.allShares) renderShares(state.allShares);
}

function beginPendingShareDeletion(s) {
  const pending = {
    id: s.id,
    timer: null,
    committing: false,
    promise: null,
  };
  state.pendingShareDeletion = pending;
  if (state.selShares) state.selShares.delete(s.id);
  pending.timer = setTimeout(() => commitPendingShareDeletion(pending.id), SHARE_DELETE_UNDO_MS);
  rerenderShareCollections();
  toast(t('sh.revokePending'), 'warn');
}

function undoPendingShareDeletion(id) {
  const pending = state.pendingShareDeletion;
  if (!pending || pending.id !== id || pending.committing) return;
  clearTimeout(pending.timer);
  state.pendingShareDeletion = null;
  rerenderShareCollections();
  toast(t('sh.recovered'), 'ok');
}

async function commitPendingShareDeletion(id) {
  const pending = state.pendingShareDeletion;
  if (!pending || pending.id !== id) return true;
  if (pending.promise) return pending.promise;
  clearTimeout(pending.timer);
  pending.committing = true;
  pending.promise = (async () => {
    try {
      await api('DELETE', '/api/shares/' + encodeURIComponent(id));
      if (state.pendingShareDeletion === pending) state.pendingShareDeletion = null;
      state.allShares = (state.allShares || []).filter((share) => share.id !== id);
      rerenderShareCollections();
      loadPhotoHistory();
      toast(t('sh.revoked'), 'ok');
      loadUndoPreview();
      return true;
    } catch (e) {
      if (state.pendingShareDeletion === pending) state.pendingShareDeletion = null;
      rerenderShareCollections();
      toast(t('sh.revokeFail'), 'err');
      return false;
    }
  })();
  return pending.promise;
}

async function revokeShare(s) {
  if (pendingShareDeletionFor(s.id)) return;
  if ((!state.settings || state.settings.confirmShareRevoke !== false) && !(await confirmDirectXferAction(t('sh.revokeConfirm', { name: s.name }), { confirmText:t('sh.revoke'), danger:true }))) return;
  // Only one share can be recoverable at once. Starting another deletion makes
  // the previous one permanent before opening a fresh five-second window.
  if (state.pendingShareDeletion) {
    await commitPendingShareDeletion(state.pendingShareDeletion.id);
  }
  beginPendingShareDeletion(s);
}

async function reactivateShare(s, button) {
  if (!s || !s.id) return;
  if (button) button.disabled = true;
  try {
    await api('POST', '/api/shares/' + encodeURIComponent(s.id) + '/reactivate', {});
    toast(t('sh.reactivateOk'), 'ok');
    await refreshShares();
  } catch (e) {
    const code = e && e.data && e.data.error;
    toast(code === 'data-missing' ? t('sh.reactivateMissing') : t('sh.reactivateFail'), 'err');
  } finally { if (button) button.disabled = false; }
}

// Duplicate a share's configuration into a fresh share. The server generates a
// new id/token, resets runtime data and safely copies managed image files.
async function cloneShare(s, button) {
  const originalName = ((s && s.name) || 'Share');
  let suggested = originalName + ' ' + t('sh.cloneSuffix');
  if (s && s.type === 'photo') {
    const match = /^(.*?)(\.(?:jpe?g|png|gif|webp|bmp|avif))$/i.exec(originalName);
    if (match) suggested = match[1] + ' ' + t('sh.cloneSuffix') + match[2];
  }
  const entered = prompt(t('sh.clonePrompt'), suggested);
  if (entered == null) return;

  const name = entered.replace(/[\r\n\t]+/g, ' ').trim().slice(0, 200);
  if (!name) {
    toast(t('sh.cloneInvalidName'), 'err');
    return;
  }

  const previousText = button && button.textContent;
  if (button) {
    button.disabled = true;
    button.textContent = t('sh.cloneBusy');
  }

  try {
    const data = await api('POST', '/api/shares/' + encodeURIComponent(s.id) + '/clone', { name });
    const duplicated = data && data.share;
    toast(t('sh.clonedAs', { name: (duplicated && duplicated.name) || name }), 'ok');
    await refreshShares();
  } catch (e) {
    const code = e.data && e.data.error;
    toast(code === 'cannot-clone' ? t('sh.cloneUnsupported')
      : code === 'image-missing' ? t('sh.cloneImageMissing')
      : code === 'invalid-name' ? t('sh.cloneInvalidName')
      : t('sh.cloneFail'), 'err');
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = previousText || t('sh.clone');
    }
  }
}

// E-mail a link to a recipient via the configured SMTP.
async function emailShare(s) {
  const to = prompt(t('sh.emailPrompt', { name: s.name }));
  if (to == null) return; // cancelled
  const addr = to.trim();
  if (!addr) return;
  try {
    await api('POST', '/api/shares/' + encodeURIComponent(s.id) + '/email', { to: addr });
    toast(t('sh.emailSent', { to: addr }), 'ok');
  } catch (e) {
    const code = e.data && e.data.error;
    toast(code === 'invalid-email' ? t('sh.emailInvalid')
      : code === 'email-not-configured' ? t('sh.emailNotConfigured')
      : t('sh.emailFail'), 'err');
  }
}

// Inline rename: turn the card's name into an input on double-click.
function startInlineRename(s, nameEl) {
  if (nameEl.querySelector('input')) return;
  const cur = s.name || '';
  const input = el('input', { class: 'name-edit', attrs: { type: 'text', maxlength: '200' } });
  input.value = cur;
  nameEl.textContent = '';
  nameEl.appendChild(input);
  input.focus(); input.select();
  let done = false;
  const commit = async (save) => {
    if (done) return; done = true;
    const v = input.value.trim();
    if (!save || !v || v === cur) { if (state.allShares) renderShares(state.allShares); return; }
    try { await api('PATCH', '/api/shares/' + encodeURIComponent(s.id), { name: v }); toast(t('sh.renamed'), 'ok'); refreshShares(); }
    catch (e) { toast(t('sh.renameFail'), 'err'); refreshShares(); }
  };
  input.addEventListener('keydown', (e) => {
    e.stopPropagation();
    if (e.key === 'Enter') { e.preventDefault(); commit(true); }
    else if (e.key === 'Escape') { e.preventDefault(); commit(false); }
  });
  input.addEventListener('blur', () => commit(true));
}

// Detailed statistics modal shared by standard links, albums and direct images.
function statsMetric(icon, value, label, detail) {
  const card = el('div', { class: 'stats-metric' });
  card.appendChild(el('span', { class: 'stats-metric-icon', text: icon }));
  const body = el('div', { class: 'stats-metric-body' });
  body.appendChild(el('strong', { text: value == null || value === '' ? '—' : String(value) }));
  body.appendChild(el('span', { text: label }));
  if (detail) body.appendChild(el('small', { text: detail }));
  card.appendChild(body);
  return card;
}

function statsSection(title) {
  const section = el('section', { class: 'stats-section' });
  section.appendChild(el('h4', { text: title }));
  return section;
}

function statsDefinitionGrid(rows) {
  const grid = el('div', { class: 'stats-definition-grid' });
  rows.filter((row) => row && row[1] !== null && row[1] !== undefined && row[1] !== '').forEach(([label, value, mono]) => {
    const item = el('div', { class: 'stats-definition' });
    item.appendChild(el('span', { text: label }));
    item.appendChild(el('strong', { class: mono ? 'stats-mono' : '', text: String(value) }));
    grid.appendChild(item);
  });
  return grid;
}

function statsBreakdown(rows, valueFormatter) {
  const box = el('div', { class: 'stats-breakdown' });
  if (!rows || !rows.length) {
    box.appendChild(el('div', { class: 'empty sm', text: t('stats.none') }));
    return box;
  }
  const max = Math.max(1, ...rows.map((row) => Number(row.count) || 0));
  rows.forEach((row) => {
    const line = el('div', { class: 'stats-breakdown-row' });
    const label = el('span', { class: 'stats-breakdown-label', text: (row.flag ? row.flag + ' ' : '') + (row.name || row.label || t('stats.unknown')) });
    const bar = el('span', { class: 'stats-breakdown-bar' });
    const fill = el('i');
    fill.style.width = Math.max(4, Math.round(((Number(row.count) || 0) / max) * 100)) + '%';
    bar.appendChild(fill);
    const value = valueFormatter ? valueFormatter(row) : String(row.count || 0);
    line.append(label, bar, el('strong', { text: value }));
    box.appendChild(line);
  });
  return box;
}

function statsTimeline(points) {
  const chart = el('div', { class: 'stats-timeline' });
  const max = Math.max(1, ...(points || []).map((p) => Number(p.bytes) || Number(p.count) || 0));
  (points || []).forEach((point) => {
    const cell = el('div', { class: 'stats-timeline-cell', attrs: { title: point.day + ' · ' + (point.count || 0) + ' · ' + formatBytes(point.bytes || 0) } });
    const bar = el('i');
    const raw = Number(point.bytes) || Number(point.count) || 0;
    bar.style.height = (raw ? Math.max(6, Math.round((raw / max) * 100)) : 2) + '%';
    cell.appendChild(bar);
    const rawLabel = String(point.day || '');
    cell.appendChild(el('span', { text: /^\d{2}:\d{2}$/.test(rawLabel) ? rawLabel : rawLabel.slice(5) }));
    chart.appendChild(cell);
  });
  return chart;
}

function statsStatusLabel(status) {
  const key = 'stats.' + String(status || 'inactive');
  const label = t(key);
  return label === key ? String(status || t('stats.unknown')) : label;
}

function statsTypeLabel(type) {
  const keys = { file: 'sh.file', folder: 'sh.folder', inbox: 'sh.inbox', collab: 'sh.collab', photo: 'photo.title', album: 'album.title' };
  const key = keys[type];
  return key ? t(key) : (type || t('stats.unknown'));
}

let detailedStatsContext = { share: null, period: '14', requestSeq: 0 };
function statsDeltaText(value, suffix = '%') {
  const n = Number(value) || 0; return (n > 0 ? '+' : '') + n + suffix;
}
function statsPeriodToolbar(data) {
  const wrap = el('div', { class: 'stats-period-toolbar' });
  wrap.appendChild(el('span', { class:'muted sm', text:t('stats.period') }));
  const select = el('select', { class:'stats-period-select' });
  [['1',t('stats.24h')],['7',t('stats.7d')],['14',t('stats.14d')],['30',t('stats.30d')],['all',t('stats.all')]].forEach(([value,label]) => {
    const o=el('option',{text:label,attrs:{value}}); if(String(detailedStatsContext.period)===value)o.selected=true; select.appendChild(o);
  });
  select.addEventListener('change',()=>{ detailedStatsContext.period=select.value; if(detailedStatsContext.share) loadDetailedStats(detailedStatsContext.share, select.value); });
  wrap.appendChild(select);
  if (data && data.period) wrap.appendChild(el('span',{class:'muted sm',text:t('stats.periodHint')}));
  return wrap;
}
function renderDetailedStats(data) {
  const body = $('stats-body');
  body.textContent = '';
  if (!data || !data.share) {
    body.appendChild(el('div', { class: 'empty', text: t('stats.none') }));
    return;
  }
  const sh = data.share;
  const ag = data.aggregate || {};
  const image = data.image;
  body.appendChild(statsPeriodToolbar(data));

  const overview = statsSection(t('stats.overview'));
  const metrics = el('div', { class: 'stats-metrics' });
  metrics.appendChild(statsMetric('🔄', (ag.count || 0).toLocaleString(), t('stats.transfers'), (ag.completed || 0) + ' / ' + (ag.interrupted || 0)));
  metrics.appendChild(statsMetric('💾', formatBytes(ag.bytes || 0), t('stats.volume'), t('stats.averageSize') + ': ' + formatBytes(ag.averageBytes || 0)));
  metrics.appendChild(statsMetric('✅', (ag.successRate || 0) + '%', t('stats.success'), t('stats.completed') + ': ' + (ag.completed || 0)));
  metrics.appendChild(statsMetric('⚡', fmtBps(ag.averageBps || 0), t('stats.speed')));
  metrics.appendChild(statsMetric('👁', ((image && image.totalViews) || sh.views || 0).toLocaleString(), t('stats.views')));
  metrics.appendChild(statsMetric('👤', ((image && image.totalVisitors) || sh.uniqueVisitors || 0).toLocaleString(), t('stats.visitors')));
  if (image) metrics.appendChild(statsMetric('🗄', formatBytes(image.totalStorageBytes || sh.logicalBytes || 0), t('stats.storage')));
  else metrics.appendChild(statsMetric('⬇', (sh.downloads || 0).toLocaleString(), t('stats.downloads')));
  metrics.appendChild(statsMetric('↻', (ag.resumed || 0).toLocaleString(), t('stats.resumed')));
  overview.appendChild(metrics);
  body.appendChild(overview);

  if (data.comparison && data.comparison.available) {
    const cmp = statsSection(t('stats.comparison')); const d = data.comparison.delta || {};
    const grid = el('div',{class:'stats-comparison-grid'});
    grid.appendChild(statsMetric('🔄', statsDeltaText(d.countPct), t('stats.transfers')));
    grid.appendChild(statsMetric('💾', statsDeltaText(d.bytesPct), t('stats.volume')));
    grid.appendChild(statsMetric('✅', statsDeltaText(d.successRatePoints, ' pt'), t('stats.success')));
    grid.appendChild(statsMetric('⚡', statsDeltaText(d.speedPct), t('stats.speed')));
    cmp.appendChild(grid); cmp.appendChild(el('p',{class:'muted sm',text:t('stats.comparisonHint')})); body.appendChild(cmp);
  }

  const details = statsSection(t('stats.details'));
  details.appendChild(statsDefinitionGrid([
    [t('stats.status'), statsStatusLabel(sh.status)],
    [t('stats.type'), statsTypeLabel(sh.type)],
    [t('stats.owner'), sh.ownerName || '—'],
    [t('stats.created'), sh.createdAt ? formatDate(sh.createdAt) : '—'],
    [t('stats.expiry'), sh.effectiveExpiresAt ? formatDate(sh.effectiveExpiresAt) : '—'],
    [t('stats.items'), (sh.itemCount || 0).toLocaleString()],
    [t('stats.storage'), formatBytes((image && image.totalStorageBytes) || sh.logicalBytes || 0)],
    [t('stats.lastActivity'), ag.lastAt ? formatDate(ag.lastAt) : '—'],
    [t('stats.firstActivity'), ag.firstAt ? formatDate(ag.firstAt) : '—'],
    [t('stats.tags'), Array.isArray(sh.tags) && sh.tags.length ? sh.tags.join(', ') : '—'],
    [t('stats.path'), sh.path || null, true],
    [t('stats.url'), sh.url || null, true],
  ]));
  body.appendChild(details);

  if (data.quota && data.quota.length) {
    const quotaSection = statsSection(t('stats.quota'));
    const quotaBox = el('div', { class: 'stats-quota-list' });
    data.quota.forEach((q) => {
      const pct = q.max ? Math.max(0, Math.min(100, Math.round((q.used / q.max) * 100))) : 0;
      const label = q.kind === 'bytes' ? t('stats.storage') : q.kind === 'files' ? t('stats.files') : q.kind === 'visitors' ? t('stats.visitors') : t('stats.downloads');
      const used = q.kind === 'bytes' ? formatBytes(q.used) : Number(q.used || 0).toLocaleString();
      const max = q.kind === 'bytes' ? formatBytes(q.max) : Number(q.max || 0).toLocaleString();
      const row = el('div', { class: 'stats-quota-row' });
      row.appendChild(el('div', { class: 'stats-quota-head', text: label + ' · ' + used + ' / ' + max + ' · ' + pct + '%' }));
      const bar = el('div', { class: 'stats-quota-bar' });
      const fill = el('i'); fill.style.width = pct + '%'; bar.appendChild(fill); row.appendChild(bar);
      quotaBox.appendChild(row);
    });
    quotaSection.appendChild(quotaBox);
    body.appendChild(quotaSection);
  }

  if (image && image.variants) {
    const section = statsSection(t('stats.imageCopies'));
    const variants = el('div', { class: 'stats-image-variants' });
    ['full', 'thumb', 'micro'].forEach((kind) => {
      const v = image.variants[kind] || {};
      const card = el('div', { class: 'stats-image-variant' + (v.present ? '' : ' missing') });
      card.appendChild(el('strong', { text: t('stats.' + kind) }));
      const dim = v.w && v.h ? v.w + '×' + v.h : '—';
      card.appendChild(el('span', { text: t('stats.dimensions') + ': ' + dim }));
      card.appendChild(el('span', { text: t('stats.storage') + ': ' + formatBytes(v.size || 0) }));
      card.appendChild(el('span', { text: t('stats.views') + ': ' + (v.views || 0).toLocaleString() }));
      card.appendChild(el('span', { text: t('stats.visitors') + ': ' + (v.visitors || 0).toLocaleString() }));
      card.appendChild(el('span', { text: t('stats.bandwidth') + ': ' + formatBytes(v.bandwidthBytes || 0) }));
      card.appendChild(el('span', { text: t('stats.viewShare') + ': ' + (v.viewSharePct || 0) + '%' }));
      card.appendChild(el('span', { text: t('stats.lastView') + ': ' + (v.lastAt ? formatDate(v.lastAt) : '—') }));
      variants.appendChild(card);
    });
    section.appendChild(variants);
    body.appendChild(section);
  }

  if (data.live && data.live.length) {
    const section = statsSection(t('stats.live'));
    const list = el('div', { class: 'stats-events' });
    data.live.forEach((event) => {
      const row = el('div', { class: 'stats-event live' });
      row.appendChild(el('span', { class: 'stats-event-icon', text: event.direction === 'up' ? '⬆' : '⬇' }));
      const main = el('div', { class: 'stats-event-main' });
      main.appendChild(el('strong', { text: event.name || sh.name }));
      main.appendChild(el('span', { text: [(event.resumed ? '↻ ' + t('stats.resumed') : ''), formatBytes(event.bytes || 0) + (event.expectedBytes ? ' / ' + formatBytes(event.expectedBytes) : ''), (event.ipName || event.ip || '—')].filter(Boolean).join(' · ') }));
      row.appendChild(main);
      list.appendChild(row);
    });
    section.appendChild(list);
    body.appendChild(section);
  }

  const timeline = statsSection(t('stats.activityPeriod'));
  timeline.appendChild(statsTimeline(data.timeline || []));
  body.appendChild(timeline);

  const split = el('div', { class: 'stats-two-columns' });
  const countries = statsSection(t('stats.countries'));
  countries.appendChild(statsBreakdown(data.countries || [], (row) => (row.count || 0).toLocaleString()));
  const clients = statsSection(t('stats.clients'));
  clients.appendChild(statsBreakdown(data.clients || [], (row) => (row.count || 0).toLocaleString()));
  split.append(countries, clients);
  body.appendChild(split);

  if (Array.isArray(data.failureReasons) && data.failureReasons.length) {
    const failures = statsSection(t('stats.failureReasons'));
    failures.appendChild(statsBreakdown(data.failureReasons.map((r)=>({label:transferFailureLabel(r.reason),count:r.count,bytes:r.bytes})), (r)=>(r.count||0)+' · '+formatBytes(r.bytes||0)));
    body.appendChild(failures);
  }

  const recentSection = statsSection(t('stats.recent'));
  const recentList = el('div', { class: 'stats-events' });
  if (!data.recent || !data.recent.length) {
    recentList.appendChild(el('div', { class: 'empty sm', text: t('stats.noRecent') }));
  } else {
    data.recent.forEach((event) => {
      const row = el('div', { class: 'stats-event' + (event.completed ? ' ok' : ' fail') });
      row.appendChild(el('span', { class: 'stats-event-icon', text: event.completed ? (event.direction === 'up' ? '⬆' : '⬇') : '⚠' }));
      const main = el('div', { class: 'stats-event-main' });
      const client = [event.flag, event.ipName || event.ip, event.country, event.recipient ? '👤 ' + event.recipient : ''].filter(Boolean).join(' · ');
      main.appendChild(el('strong', { text: event.name || sh.name }));
      const detailBits = [formatBytes(event.bytes || 0), fmtDuration(event.durationMs || 0), fmtBps(event.avgBps || 0), client];
      if (event.resumed) detailBits.unshift('↻ ' + t('stats.resumed') + (event.resumeOffset ? ' ' + formatBytes(event.resumeOffset) : ''));
      main.appendChild(el('span', { text: detailBits.filter(Boolean).join(' · ') }));
      if (!event.completed && event.reason) main.appendChild(el('small', { text: transferFailureLabel(event.reason) }));
      row.appendChild(main);
      row.appendChild(el('time', { text: event.at ? timeAgo(event.at) : '—' }));
      recentList.appendChild(row);
    });
  }
  recentSection.appendChild(recentList);
  body.appendChild(recentSection);

  if (image) {
    const imageRecent = statsSection(t('stats.imageRecent'));
    const list = el('div', { class: 'stats-events' });
    if (!image.recentViews || !image.recentViews.length) {
      list.appendChild(el('div', { class: 'empty sm', text: t('stats.noImageRecent') }));
    } else {
      image.recentViews.forEach((event) => {
        const row = el('div', { class: 'stats-event' });
        row.appendChild(el('span', { class: 'stats-event-icon', text: event.kind === 'full' ? '🖼' : event.kind === 'thumb' ? '▣' : '▫' }));
        const main = el('div', { class: 'stats-event-main' });
        main.appendChild(el('strong', { text: t('stats.' + event.kind) }));
        const visitorCountry = event.country ? countryText(event.country) : t('stats.unknown');
        main.appendChild(el('span', { text: [event.flag || '🌐', event.ip || '—', visitorCountry].join(' · ') }));
        row.appendChild(main);
        row.appendChild(el('time', { text: event.at ? timeAgo(event.at) : '—' }));
        list.appendChild(row);
      });
    }
    imageRecent.appendChild(list);
    body.appendChild(imageRecent);
  }
}

async function loadDetailedStats(s, period) {
  const seq = ++detailedStatsContext.requestSeq;
  const body = $('stats-body'); body.textContent = t('stats.loading');
  try {
    const data = await api('GET', '/api/shares/' + encodeURIComponent(s.id) + '/stats-detail?period=' + encodeURIComponent(period || '14'));
    if (seq !== detailedStatsContext.requestSeq) return;
    renderDetailedStats(data);
  } catch (_) { if (seq === detailedStatsContext.requestSeq) body.textContent = t('stats.fail'); }
}
async function openDetailedStats(s) {
  detailedStatsContext.share = s; detailedStatsContext.period = detailedStatsContext.period || '14';
  $('stats-title').textContent = t('stats.title'); $('stats-subtitle').textContent = s.name || '';
  $('stats-overlay').classList.remove('hidden');
  await loadDetailedStats(s, detailedStatsContext.period);
}
function closeDetailedStats() { detailedStatsContext.requestSeq += 1; detailedStatsContext.share = null; $('stats-overlay').classList.add('hidden'); }

// Per-link access log modal.
async function openAccessLog(s) {
  $('log-title').textContent = s.name;
  const body = $('log-body');
  body.textContent = t('log.loading');
  $('log-overlay').classList.remove('hidden');
  try {
    const r = await api('GET', '/api/shares/' + encodeURIComponent(s.id) + '/log');
    body.textContent = '';
    const entries = (r && r.entries) || [];
    if (!entries.length) { body.appendChild(el('div', { class: 'empty', text: t('log.none') })); return; }
    entries.forEach((e) => {
      const row = el('div', { class: 'log-row' });
      row.appendChild(el('span', { class: 'log-dir', text: e.direction === 'up' ? '⬆' : '⬇' }));
      const main = el('div', { class: 'log-main' });
      main.appendChild(el('div', { class: 'log-line1',
        text: (e.flag ? e.flag + ' ' : '') + (e.ip || '—') + (e.country ? ' · ' + e.country : '') + (e.recipient ? ' · 👤 ' + e.recipient : '') }));
      main.appendChild(el('div', { class: 'log-line2 muted sm',
        text: formatBytes(e.bytes) + ' · ' + (e.completed ? t('log.ok') : t('log.ko')) + ' · ' + timeAgo(e.at) + (e.name ? ' · ' + e.name : '') }));
      row.appendChild(main);
      body.appendChild(row);
    });
  } catch (e) { body.textContent = t('log.fail'); }
}
function closeAccessLog() { $('log-overlay').classList.add('hidden'); }

// Received-file browser with thumbnails for reception/collab links.
// Images render a real (CSS-scaled) thumbnail via the authenticated inline route;
// every file offers a download. The thumbnail count is capped so a folder with
// thousands of images can't fire thousands of requests at once.
const RECEIVED_THUMB_CAP = 300;
async function openReceivedFiles(s) {
  if ($('received-subtitle')) $('received-subtitle').textContent = s.name || '';
  const body = $('received-body');
  if (!body) return;
  body.textContent = t('recv.loading');
  $('received-overlay').classList.remove('hidden');
  try {
    const r = await api('GET', '/api/shares/' + encodeURIComponent(s.id) + '/received');
    body.textContent = '';
    const files = (r && r.files) || [];
    if ($('received-subtitle')) $('received-subtitle').textContent = (s.name || '') + ' · ' + t('recv.count', { n: files.length });
    if (!files.length) { body.appendChild(el('div', { class: 'empty', text: t('recv.empty') })); return; }
    const grid = el('div', { class: 'received-grid' });
    let thumbs = 0;
    files.forEach((f) => {
      const card = el('div', { class: 'received-card' });
      const dlUrl = '/api/shares/' + encodeURIComponent(s.id) + '/received-file?path=' + encodeURIComponent(f.path);
      const media = el('div', { class: 'received-thumb' });
      if (f.image && thumbs < RECEIVED_THUMB_CAP) {
        thumbs += 1;
        const img = el('img', { attrs: { loading: 'lazy', alt: f.name } });
        img.src = dlUrl + '&inline=1';
        img.addEventListener('error', () => { media.textContent = ''; media.appendChild(el('span', { class: 'received-ico', text: '🖼' })); }, { once: true });
        media.appendChild(img);
      } else {
        media.appendChild(el('span', { class: 'received-ico', text: f.image ? '🖼' : '📄' }));
      }
      card.appendChild(media);
      const meta = el('div', { class: 'received-meta' });
      meta.appendChild(el('div', { class: 'received-name', text: f.name, attrs: { title: f.path } }));
      meta.appendChild(el('div', { class: 'received-sub muted sm', text: formatBytes(f.size || 0) + (f.mtime ? ' · ' + timeAgo(f.mtime) : '') }));
      const dl = el('a', { class: 'btn ghost xs', text: t('recv.download'), attrs: { href: dlUrl, download: f.name || '', rel: 'noopener' } });
      meta.appendChild(dl);
      card.appendChild(meta);
      grid.appendChild(card);
    });
    body.appendChild(grid);
  } catch (e) { body.textContent = t('recv.fail'); }
}
function closeReceivedFiles() { if ($('received-overlay')) $('received-overlay').classList.add('hidden'); }
if ($('received-close')) $('received-close').addEventListener('click', closeReceivedFiles);
if ($('received-overlay')) $('received-overlay').addEventListener('click', (e) => { if (e.target === $('received-overlay')) closeReceivedFiles(); });

if ($('stats-close')) $('stats-close').addEventListener('click', closeDetailedStats);
if ($('stats-overlay')) $('stats-overlay').addEventListener('click', (e) => { if (e.target === $('stats-overlay')) closeDetailedStats(); });
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && $('stats-overlay') && !$('stats-overlay').classList.contains('hidden')) closeDetailedStats();
});


// Recoverable trash UI.
async function restoreTrashSmart(id,row){try{await api('POST','/api/trash/'+encodeURIComponent(id)+'/restore',{});return true;}catch(err){const data=err&&err.data||err&&err.body||null;if(!(data&&data.error==='restore-location-missing'))throw err;const alternatives=data.assessment&&Array.isArray(data.assessment.alternatives)?data.assessment.alternatives:[];let path=alternatives[0]||'';if(path&&confirm(t('trash.smartRestore',{path}))){}else{path=prompt(t('trash.chooseRestore'),path||'')||'';}if(!path)throw err;await api('POST','/api/trash/'+encodeURIComponent(id)+'/restore',{alternativePath:path});return true;}}
async function loadTrash(){
  const body=$('trash-body');if(!body)return;body.textContent=t('filehist.loading');
  try{
    const data=await api('GET','/api/trash'),items=(data&&data.items)||[];state.trashPurgeSummary=data&&data.purgeSummary||null;
    const valid=new Set(items.map((r)=>r.id));for(const id of [...state.trashSelection])if(!valid.has(id))state.trashSelection.delete(id);
    const badge=$('trash-count-badge');if(badge)badge.textContent=String(items.length);
    body.textContent='';if($('trash-subtitle'))$('trash-subtitle').textContent=t('trash.retention',{n:data.retentionDays||0});
    const updateSelected=()=>{const n=state.trashSelection.size,btn=$('trash-restore-selected'),label=$('trash-selected-count');if(btn){btn.classList.toggle('hidden',!n||state.role==='auditor');btn.disabled=!n||state.role==='auditor';btn.textContent=t('trash.restoreSelectedN',{n});}if(label)label.textContent=n?t('trash.selected',{n}):'';};
    if(!items.length){body.appendChild(el('div',{class:'empty',text:t('trash.empty')}));updateSelected();return;}
    items.forEach((r)=>{
      const row=el('div',{class:'trash-row'+(state.trashSelection.has(r.id)?' selected':'')}),main=el('div',{class:'trash-main'});
      if(state.role!=='auditor'){
        const check=el('input',{class:'trash-select',attrs:{type:'checkbox','aria-label':t('trash.select')}});check.checked=state.trashSelection.has(r.id);
        check.addEventListener('change',()=>{if(check.checked)state.trashSelection.add(r.id);else state.trashSelection.delete(r.id);row.classList.toggle('selected',check.checked);updateSelected();});row.appendChild(check);
      }
      main.appendChild(el('strong',{text:r.name||'—'}));main.appendChild(el('span',{class:'muted sm',text:[r.type||'',formatBytes(r.logicalBytes||0),r.deletedAt?timeAgo(r.deletedAt):''].filter(Boolean).join(' · ')}));const impact=r.purgeImpact||{};main.appendChild(el('span',{class:'muted xs trash-impact',text:t('trash.impact',{count:impact.itemCount||1,bytes:formatBytes(impact.bytes!=null?impact.bytes:(r.logicalBytes||0))})}));main.appendChild(el('span',{class:'muted xs trash-deps',text:t('trash.dependencies',{value:(impact.dependencies&&impact.dependencies.length)?impact.dependencies.join(', '):t('trash.noDependencies')})}));if(r.deletedBy)main.appendChild(el('span',{class:'muted xs',text:r.deletedBy}));
      const acts=el('div',{class:'trash-actions'});const historyBtn=el('button',{class:'btn ghost sm',text:t('sh.historyBtn')});historyBtn.addEventListener('click',()=>openShareChangeHistory({id:r.shareId,name:r.name,trashId:r.id}));acts.appendChild(historyBtn);
      if(state.role!=='auditor'){const restore=el('button',{class:'btn sm',text:t('trash.restore')});restore.addEventListener('click',async()=>{try{await restoreTrashSmart(r.id,r);state.trashSelection.delete(r.id);toast(t('trash.restoreOk'),'ok');await loadTrash();loadUndoPreview();refreshShares();}catch(_){toast(t('trash.restoreFail'),'err');}});acts.appendChild(restore);}
      if(state.role==='owner'||state.role==='admin'){const purge=el('button',{class:'btn danger sm',text:t('trash.purge')});purge.addEventListener('click',async()=>{const imp=r.purgeImpact||{},deps=imp.dependencyCount?' · '+t('trash.dependencies',{value:(imp.dependencies||[]).join(', ')}):'';if(!confirm(t('trash.purgeConfirmImpact',{name:r.name||'',bytes:formatBytes(imp.bytes!=null?imp.bytes:(r.logicalBytes||0)),count:imp.itemCount||1,deps})))return;try{await api('DELETE','/api/trash/'+encodeURIComponent(r.id));state.trashSelection.delete(r.id);toast(t('trash.purgeOk'),'ok');loadTrash();loadUndoPreview();refreshShares();}catch(_){toast(t('trash.purgeFail'),'err');}});acts.appendChild(purge);}
      row.append(main,acts);body.appendChild(row);
    });updateSelected();
  }catch(_){
    state.trashSelection.clear();
    const btn=$('trash-restore-selected'),label=$('trash-selected-count');
    if(btn){btn.classList.add('hidden');btn.disabled=true;}
    if(label)label.textContent='';
    body.textContent=t('sh.loadFail');
  }
}
async function restoreSelectedTrash(){
  const ids=[...state.trashSelection];if(!ids.length)return;
  const btn=$('trash-restore-selected');if(btn)btn.disabled=true;
  let ok=0,failed=0;
  for(const id of ids){try{await restoreTrashSmart(id,null);state.trashSelection.delete(id);ok++;}catch(_){failed++;}}
  if(ok)toast(t('trash.restoreSelectedOk',{n:ok}),'ok');if(failed)toast(t('trash.restoreSelectedFail',{n:failed}),'err');
  await loadTrash();loadUndoPreview();refreshShares();
}
function openTrash(){$('trash-overlay').classList.remove('hidden');loadTrash();}function closeTrash(){$('trash-overlay').classList.add('hidden');}
if($('trash-btn'))$('trash-btn').addEventListener('click',openTrash);if($('trash-close'))$('trash-close').addEventListener('click',closeTrash);if($('trash-overlay'))$('trash-overlay').addEventListener('click',(e)=>{if(e.target===$('trash-overlay'))closeTrash();});if($('trash-restore-selected'))$('trash-restore-selected').addEventListener('click',restoreSelectedTrash);if($('trash-purge-all'))$('trash-purge-all').addEventListener('click',async()=>{const sum=state.trashPurgeSummary||{},deps=sum.dependencies?' · '+t('trash.dependencies',{value:String(sum.dependencies)}):'';if(!confirm(t('trash.purgeAllImpact',{count:sum.items||0,bytes:formatBytes(sum.bytes||0),deps})))return;try{await api('DELETE','/api/trash');state.trashSelection.clear();toast(t('trash.purgeOk'),'ok');loadTrash();loadUndoPreview();refreshShares();}catch(_){toast(t('trash.purgeFail'),'err');}});

// Undoable-action history (#89), merged directly into the Activity tab.
// There is deliberately no separate card/modal in the standard UI: the durable
// Undo journal enriches matching Activity rows and supplies a synthetic Activity
// row only when the original activity event is outside the retained window.
const UNDO_TYPE_KEY={'settings-changed':'undo.type.settings','share-stats-reset':'undo.type.stats','recipient-removed':'undo.type.recipient','ip-names-cleared':'undo.type.ipnames','share-trashed':'undo.type.share'};
const UNDO_REASON_KEY={'state-changed':'undo.reason.changed','already-restored':'undo.reason.restored','already-purged':'undo.reason.purged','legacy-unsafe':'undo.reason.legacy','forbidden':'undo.reason.forbidden','share-gone':'undo.reason.gone','undo-unsupported':'undo.reason.unsupported','restore-conflict':'undo.reason.restoreConflict','undo-too-large':'undo.reason.tooLarge'};
function undoTypeLabel(e){const k=UNDO_TYPE_KEY[e.type];return k?t(k):(e.type||'');}
function undoConfirmLabel(e){return [undoTypeLabel(e),e&&e.label||''].filter(Boolean).join(' — ');}
function undoCanRun(e){return !!(e&&!e.undone&&e.canUndo!==false);}
function undoStatusText(e){if(e&&e.undone)return t('undo.done');if(e&&e.canUndo===false){const k=UNDO_REASON_KEY[e.unavailableReason];return k?t(k):t('undo.unavailable');}return '';}
async function fetchUndoItems(){const data=await api('GET','/api/undo');return (data&&Array.isArray(data.items))?data.items:[];}
function undoMatchesActivity(undo,event){
  if(!undo||!event)return false;
  const dt=Math.abs((Number(undo.at)||0)-(Number(event.at)||0));
  if(dt>15000)return false;
  const actorOk=!undo.actor||!event.actor||String(undo.actor)===String(event.actor);
  if(!actorOk)return false;
  const kind=String(event.kind||''), name=String(event.name||''), status=String(event.status||'');
  if(name===String(undo.type||'')||status===String(undo.type||''))return true;
  if(undo.type==='share-trashed'&&kind==='trash'&&status==='deleted'){
    const label=String(undo.label||'').trim(), eventName=String(event.name||'').trim();
    return !label||!eventName||label===eventName||label.endsWith(' '+eventName);
  }
  return false;
}
function activityEventsWithUndo(){
  const rows=(state.activityEvents||[]).map((e)=>({...e}));
  const claimed=new Set();
  (state.undoItems||[]).forEach((undo)=>{
    let best=-1,bestDt=Infinity;
    for(let i=0;i<rows.length;i++){
      if(claimed.has(i)||rows[i]._undo||!undoMatchesActivity(undo,rows[i]))continue;
      const dt=Math.abs((Number(undo.at)||0)-(Number(rows[i].at)||0));
      if(dt<bestDt){best=i;bestDt=dt;}
    }
    if(best>=0){rows[best]._undo=undo;claimed.add(best);return;}
    rows.push({
      id:'undo:'+undo.id, at:undo.at||0, kind:'undo-action', status:undo.undone?'undone':undoCanRun(undo)?'undoable':'unavailable',
      name:undoTypeLabel(undo), detail:undo.label||'', actor:undo.actor||'', _undo:undo,
    });
  });
  rows.sort((a,b)=>(Number(b.at)||0)-(Number(a.at)||0));
  return rows;
}
async function loadUndoActivityItems({render=true}={}){
  if(state.undoLoading||!isLoggedIn()||!['owner','admin','auditor',''].includes(state.role||''))return state.undoItems||[];
  state.undoLoading=true;
  try{state.undoItems=await fetchUndoItems();if(render)renderActivity();return state.undoItems;}
  catch(_){state.undoItems=[];if(render)renderActivity();return [];}
  finally{state.undoLoading=false;}
}
async function runUndoFromActivity(undo,button){
  if(!undoCanRun(undo))return;
  if(!confirm(t('undo.confirm',{label:undoConfirmLabel(undo)})))return;
  if(button)button.disabled=true;
  try{
    await api('POST','/api/undo/'+encodeURIComponent(undo.id),{});
    toast(t('undo.ok'),'ok');
    await Promise.allSettled([loadUndoActivityItems({render:false}),loadActivityRecent(),loadTrash()]);
    refreshShares();renderActivity();
  }catch(_){
    toast(t('undo.fail'),'err');
    await Promise.allSettled([loadUndoActivityItems({render:false}),loadActivityRecent()]);
    if(button)button.disabled=false;
    renderActivity();
  }
}
// Compatibility hook used by existing mutation paths. It now refreshes the
// Activity-integrated Undo data instead of a removed dashboard preview.
function loadUndoPreview(){return loadUndoActivityItems();}
function loadUndoLog(){return loadUndoActivityItems();}

// Detailed per-file download history.
async function openFileHistory(sh){$('file-history-subtitle').textContent=sh.name||'';const body=$('file-history-body');body.textContent=t('filehist.loading');$('file-history-overlay').classList.remove('hidden');try{const data=await api('GET','/api/shares/'+encodeURIComponent(sh.id)+'/file-history');body.textContent='';if(data&&(data.historyTruncated||data.zipMembersTruncated))body.appendChild(el('div',{class:'notice warn',text:t('filehist.truncated')}));const files=(data&&data.files)||[];if(!files.length){body.appendChild(el('div',{class:'empty',text:t('filehist.empty')}));return;}files.forEach((f)=>{const box=el('div',{class:'filehist-file'}),head=el('div',{class:'filehist-head'});head.appendChild(el('strong',{text:f.name||'—'}));head.appendChild(el('span',{text:t('filehist.transfers',{n:f.transfers||0})+' · '+formatBytes(f.bytes||0)}));box.appendChild(head);box.appendChild(el('div',{class:'muted sm',text:t('filehist.completed',{n:f.completed||0})+' · '+(f.lastAt?t('filehist.last',{v:timeAgo(f.lastAt)}):'—')+(f.lastIp?' · '+f.lastIp:'')+(f.lastCountry?' · '+f.lastCountry:'')}));((data&&data.events)||[]).filter((e)=>e.name===f.name).slice(0,20).forEach((e)=>{const row=el('div',{class:'filehist-event '+(e.completed?'ok':'fail')});row.appendChild(el('span',{text:e.completed?'✓':'⚠'}));row.appendChild(el('span',{text:[e.at?formatDate(e.at):'—',e.viaZip?'📦 ZIP':'',formatBytes(e.bytes||0),e.ipName||e.ip||'—',e.country||'',e.recipient?'👤 '+e.recipient:'',e.completed?'':(e.reason||'')].filter(Boolean).join(' · ')}));box.appendChild(row);});body.appendChild(box);});}catch(_){body.textContent=t('filehist.fail');}}
function closeFileHistory(){$('file-history-overlay').classList.add('hidden');}if($('file-history-close'))$('file-history-close').addEventListener('click',closeFileHistory);if($('file-history-overlay'))$('file-history-overlay').addEventListener('click',(e)=>{if(e.target===$('file-history-overlay'))closeFileHistory();});

// Persistent activity history + real-time SSE stream.
function activityIcon(kind,status){if(kind==='transfer-start')return'⇄';if(kind==='transfer-complete')return'✓';if(kind==='transfer-error')return'⚠';if(kind==='ocr-start'||kind==='ocr-complete')return'T';if(kind==='ocr-error')return'⚠';if(kind==='antivirus')return status==='infected'?'🦠':'🛡';if(kind==='trash')return'🗑';if(kind==='security')return'🔐';if(kind==='visitor')return'👥';if(kind==='system')return'⚙';if(kind==='share')return'🔗';if(kind==='audit')return'🧾';if(kind==='undo-action')return'↶';return'•';}
function activityGroup(e){const k=String(e&&e.kind||'').toLowerCase();if(k.indexOf('transfer-')===0)return'transfer';if(k==='audit'||k==='share'||k==='trash'||k==='undo-action')return'admin';if(k==='security'||k==='antivirus')return'security';if(k==='visitor')return'visitor';if(k==='system'||k.indexOf('ocr-')===0)return'system';return'admin';}
