// --- Drag-drop / paste / host-picker image uploads -----------------
// The privacy option is snapshotted at the start of each batch so every image in
// that batch follows the same policy, even if the checkbox changes mid-upload.
const PHOTO_UPLOAD_ALLOWED = /\.(jpe?g|png|gif|webp|bmp|avif)$/i;

function namedPhotoBlob(blob, name, type, lastModified) {
  try { return new File([blob], name, { type: type || blob.type || 'application/octet-stream', lastModified: lastModified || Date.now() }); }
  catch (_) {
    try { Object.defineProperty(blob, 'name', { value: name, configurable: true }); } catch (_) { blob.name = name; }
    return blob;
  }
}

function loadPhotoImageElement(file) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    const url = encodeURI(URL.createObjectURL(file));
    image.onload = () => { URL.revokeObjectURL(url); resolve(image); };
    image.onerror = (error) => { URL.revokeObjectURL(url); reject(error); };
    image.src = url;
  });
}

async function loadPhotoImage(file) {
  if ('createImageBitmap' in window) {
    try { return await createImageBitmap(file, { imageOrientation: 'from-image' }); }
    catch (_) {
      try { return await createImageBitmap(file); }
      catch (_) {}
    }
  }
  return loadPhotoImageElement(file);
}

function photoCanvasBlob(canvas, type, quality) {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => blob ? resolve(blob) : reject(new Error('encode-failed')), type, quality);
  });
}

async function preparePhotoUpload(file, stripMetadata) {
  const originalName = file.name || ('image-' + Date.now() + '.jpg');
  const originalType = file.type || 'application/octet-stream';
  if (!stripMetadata) {
    return { blob: file, name: originalName, type: originalType, metadataStripped: false };
  }

  // A canvas round-trip creates new pixel data with no EXIF, GPS, XMP, comments
  // or other source metadata. It also applies phone-camera orientation before the
  // metadata is discarded. Nothing is sent to the server until this succeeds.
  let image;
  try { image = await loadPhotoImage(file); }
  catch (_) { throw new Error('metadata-decode-failed'); }
  try {
    const width = image.naturalWidth || image.width;
    const height = image.naturalHeight || image.height;
    if (!width || !height) throw new Error('metadata-dimensions-failed');

    const ext = ((originalName.split('.').pop() || '').toLowerCase()).replace('jpeg', 'jpg');
    const preserveAlpha = ext === 'png' || ext === 'webp';
    const requestedType = ext === 'png' ? 'image/png' : ext === 'webp' ? 'image/webp' : 'image/jpeg';
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext('2d', { alpha: preserveAlpha });
    if (!context) throw new Error('metadata-canvas-failed');
    if (!preserveAlpha) { context.fillStyle = '#fff'; context.fillRect(0, 0, width, height); }
    context.drawImage(image, 0, 0, width, height);

    const blob = await photoCanvasBlob(canvas, requestedType,
      requestedType === 'image/jpeg' || requestedType === 'image/webp' ? 0.94 : undefined);
    const actualType = blob.type || requestedType;
    const outExt = actualType === 'image/png' ? '.png' : actualType === 'image/webp' ? '.webp' : '.jpg';
    const base = originalName.replace(/\.[^.\/]+$/, '') || ('image-' + Date.now());
    return {
      blob: namedPhotoBlob(blob, base + outExt, actualType, file.lastModified),
      name: base + outExt,
      type: actualType,
      metadataStripped: true,
    };
  } finally {
    if (image && image.close) image.close();
  }
}

async function fetchHostPhotoFile(hostPath) {
  const response = await fetch('/api/photos/source', {
    method: 'POST', credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf || '' },
    body: JSON.stringify({ path: hostPath }),
  });
  if (!response.ok) {
    const data = await response.json().catch(() => ({}));
    const error = new Error(data.error || ('http-' + response.status));
    if (data.error === 'not-image') error.dxSkip = true;
    throw error;
  }
  const blob = await response.blob();
  let name = response.headers.get('X-Direct-Xfer-Filename') || '';
  try { name = decodeURIComponent(name); } catch (_) {}
  if (!name) name = String(hostPath || '').split(/[\\/]/).pop() || ('image-' + Date.now());
  return namedPhotoBlob(blob, name, blob.type || response.headers.get('Content-Type') || 'application/octet-stream', Date.now());
}

async function runPhotoUploadBatch(tasks, initialSkipped = 0, stripMetadata = false) {
  if (state.photoUploadBusy || !tasks.length) return;
  state.photoUploadBusy = true;
  let ok = 0, failed = 0, skipped = initialSkipped, cleaned = 0, done = 0, cursor = 0;
  const wrap = $('photos-upload-progress'), meter = $('photos-upload-meter'), status = $('photos-upload-status');
  if (wrap) wrap.classList.remove('hidden');
  if (meter) { meter.max = tasks.length; meter.value = 0; }
  const updateProgress = () => {
    if (meter) meter.value = done;
    if (status) status.textContent = t('photo.uploadProgress', { done, total: tasks.length });
  };
  updateProgress();

  const worker = async () => {
    while (cursor < tasks.length) {
      const task = tasks[cursor++];
      try {
        if (stripMetadata && status) status.textContent = t('photo.cleaningMetadata') + ' ' + (done + 1) + '/' + tasks.length;
        const file = await task();
        const prepared = await preparePhotoUpload(file, stripMetadata);
        const typeExt = ((prepared.type || '').split('/')[1] || '').toLowerCase().replace('jpeg', 'jpg');
        const name = (prepared.name && /\.[a-z0-9]+$/i.test(prepared.name))
          ? prepared.name : ('image-' + Date.now() + (typeExt ? '.' + typeExt : '.jpg'));
        let uploadUrl = '/api/photos/upload?name=' + encodeURIComponent(name);
        if (prepared.metadataStripped) uploadUrl += '&metadataRemoved=1';
        const sendPhoto = (url) => fetch(url, {
          method: 'POST', credentials: 'same-origin',
          headers: { 'Content-Type': prepared.type || 'application/octet-stream', 'X-CSRF-Token': state.csrf || '' },
          body: prepared.blob,
        });
        let response = await sendPhoto(uploadUrl), policyUrl = uploadUrl, duplicateApproved = false, dlpApproved = false;
        for (let guard = 0; response.status === 409 && guard < 3; guard++) {
          const issue = await response.clone().json().catch(() => ({}));
          if (issue.error === 'duplicate-content' && !duplicateApproved && window.confirm(t('imgDuplicateFound'))) {
            duplicateApproved = true; policyUrl += (policyUrl.includes('?') ? '&' : '?') + 'duplicateOverride=1'; response = await sendPhoto(policyUrl); continue;
          }
          if (issue.error === 'dlp-warning' && !dlpApproved && confirmDlpWarning(issue)) {
            dlpApproved = true; policyUrl += (policyUrl.includes('?') ? '&' : '?') + 'dlpOverride=1'; response = await sendPhoto(policyUrl); continue;
          }
          break;
        }
        if (!response.ok) {
          const denied = await response.clone().json().catch(() => ({}));
          if (denied.error === 'dlp-blocked' || denied.error === 'dlp-quarantined' || denied.error === 'dlp-quarantine-failed') {
            toast(denied.error === 'dlp-quarantined' ? t('dlp.quarantined') : denied.error === 'dlp-quarantine-failed' ? t('dlp.quarantineFailed') : t('dlp.blocked'), 'err');
          }
          throw new Error('upload');
        }
        const data = await response.json();
        ok += 1;
        if (prepared.metadataStripped) cleaned += 1;
        if (data && data.share) generatePhotoVariants(data.share).catch(() => {});
      } catch (error) {
        if (error && error.dxSkip) skipped += 1;
        else failed += 1;
      }
      done += 1;
      updateProgress();
    }
  };

  try {
    await Promise.all(Array.from({ length: Math.min(3, tasks.length) }, () => worker()));
  } finally {
    state.photoUploadBusy = false;
  }
  const parts = [t('photo.uploadSummary', { ok, failed, skipped })];
  if (cleaned) parts.push(t('photo.metadataCleaned', { n: cleaned }));
  const summary = parts.join(' · ');
  if (status) status.textContent = summary;
  toast(summary, failed ? (ok ? 'warn' : 'err') : 'ok');
  if (ok) refreshShares();
  setTimeout(() => { if (!state.photoUploadBusy && wrap) wrap.classList.add('hidden'); }, 4000);
}

async function uploadHostImagePaths(paths, stripMetadata) {
  const incoming = [...paths];
  const selected = incoming.slice(0, 100);
  const tasks = selected.map((hostPath) => () => fetchHostPhotoFile(hostPath));
  await runPhotoUploadBatch(tasks, Math.max(0, incoming.length - selected.length), !!stripMetadata);
}

async function uploadImageFiles(fileList) {
  const incoming = [...fileList];
  const files = incoming.slice(0, 100).filter((file) => file && ((file.type || '').startsWith('image/') || PHOTO_UPLOAD_ALLOWED.test(file.name || '')));
  const skipped = Math.max(0, incoming.length - files.length);
  if (!files.length) { toast(t('photo.uploadFail'), 'err'); return; }
  const stripMetadata = !!state.photoStripExif;
  await runPhotoUploadBatch(files.map((file) => async () => file), skipped, stripMetadata);
}
const photosStripExif = $('photos-strip-exif');
if (photosStripExif) photosStripExif.addEventListener('change', () => {
  state.photoStripExif = !!photosStripExif.checked;
  updateUiPrefs({ photoStripExif: state.photoStripExif }, true);
});

const photosDropzone = $('photos-dropzone');
if (photosDropzone) {
  const fileInput = $('photos-file-input');
  if (fileInput) fileInput.addEventListener('change', () => { uploadImageFiles(fileInput.files); fileInput.value = ''; });
  ['dragenter', 'dragover'].forEach((ev) => photosDropzone.addEventListener(ev, (e) => { e.preventDefault(); photosDropzone.classList.add('dragover'); }));
  ['dragleave', 'dragend', 'drop'].forEach((ev) => photosDropzone.addEventListener(ev, (e) => { e.preventDefault(); photosDropzone.classList.remove('dragover'); }));
  photosDropzone.addEventListener('drop', (e) => { if (e.dataTransfer && e.dataTransfer.files.length) uploadImageFiles(e.dataTransfer.files); });
}
// Paste an image anywhere on the Images page → create a link.
document.addEventListener('paste', (e) => {
  const page = $('images-page');
  if (!page || page.classList.contains('hidden')) return;
  const tag = (e.target && e.target.tagName) || '';
  if (tag === 'INPUT' || tag === 'TEXTAREA') return; // don't hijack text fields
  const items = e.clipboardData && e.clipboardData.items;
  if (!items) return;
  const files = [];
  for (const it of items) { if (it.kind === 'file' && it.type.indexOf('image/') === 0) { const f = it.getAsFile(); if (f) files.push(f); } }
  if (files.length) { e.preventDefault(); uploadImageFiles(files); }
});

// --- Multi-select + bulk actions (revoke / set expiry) ---
function updatePhotoBulkBar() {
  const bar = $('photos-bulk-bar');
  if (!bar) return;
  const n = state.photoSelection.size;
  bar.classList.toggle('hidden', n === 0);
  const cnt = $('photos-bulk-count');
  if (cnt) cnt.textContent = t('photo.selectedN', { n });
  const favorite = $('photos-bulk-favorite');
  if (favorite) {
    const photos = Array.isArray(state.photosData) ? state.photosData : [];
    const selected = photos.filter((photo) => state.photoSelection.has(photo.id));
    const allFavorites = n > 0 && selected.length === n && selected.every((photo) => !!photo.favorite);
    const action = allFavorites ? 'unfavorite' : 'favorite';
    const key = allFavorites ? 'photo.bulkUnfavorite' : 'photo.bulkFavorite';
    favorite.dataset.action = action;
    favorite.setAttribute('data-i18n', key);
    favorite.setAttribute('aria-pressed', allFavorites ? 'true' : 'false');
    favorite.textContent = t(key);
  }
}
async function photoBulk(action, extra) {
  const ids = [...state.photoSelection];
  if (!ids.length) return;
  try {
    const r = await api('POST', '/api/shares/bulk', Object.assign({ ids, action }, extra || {}));
    toast(t('sh.bulkDone', { n: (r && r.count) || 0 }), 'ok');
    state.photoSelection.clear();
    updatePhotoBulkBar();
    refreshShares();
    if (action === 'revoke') loadUndoPreview();
  } catch (e) { toast(t('sh.bulkFail'), 'err'); }
}
if ($('photos-bulk-revoke')) $('photos-bulk-revoke').addEventListener('click', async () => {
  const n = state.photoSelection.size;
  if (!n) return;
  if ((!state.settings || state.settings.confirmShareRevoke !== false) && !(await confirmDirectXferAction(t('sh.bulkRevokeConfirm', { n }), { confirmText:t('sh.bulkRevoke'), danger:true }))) return;
  photoBulk('revoke');
});
if ($('photos-bulk-expiry')) $('photos-bulk-expiry').addEventListener('change', (e) => {
  const v = e.target.value;
  e.target.value = '';
  if (v !== '' && state.photoSelection.size) photoBulk('extend', { expiresInSeconds: parseInt(v, 10) });
});
if ($('photos-bulk-album-add')) $('photos-bulk-album-add').addEventListener('change', (e) => {
  const albumId = e.target.value;
  e.target.value = '';
  if (albumId && state.photoSelection.size) photoBulk('album-add', { albumId });
});
if ($('photos-bulk-favorite')) $('photos-bulk-favorite').addEventListener('click', (e) => {
  photoBulk(e.currentTarget.dataset.action === 'unfavorite' ? 'unfavorite' : 'favorite');
});
if ($('photos-bulk-download')) $('photos-bulk-download').addEventListener('click', () => {
  const ids = [...state.photoSelection].slice(0, 100);
  if (ids.length) window.location.assign('/api/photos/download.zip?ids=' + encodeURIComponent(ids.join(',')));
});
if ($('photos-bulk-clear')) $('photos-bulk-clear').addEventListener('click', () => {
  state.photoSelection.clear();
  updatePhotoBulkBar();
  const list = $('photos-list');
  if (list) list.querySelectorAll('.photo-select input').forEach((cb) => { cb.checked = false; cb.closest('.photo-card').classList.remove('selected'); });
});
// Turn the current image selection into a shareable public gallery.
if ($('photos-bulk-album')) $('photos-bulk-album').addEventListener('click', async () => {
  const ids = [...state.photoSelection];
  if (!ids.length) return;
  const name = prompt(t('album.namePrompt'));
  if (name === null) return; // cancelled
  try {
    await api('POST', '/api/photos/album', { ids, name: name || '' });
    state.photoSelection.clear();
    updatePhotoBulkBar();
    const list = $('photos-list');
    if (list) list.querySelectorAll('.photo-select input').forEach((cb) => { cb.checked = false; cb.closest('.photo-card').classList.remove('selected'); });
    toast(t('album.created'), 'ok');
    refreshShares();
  } catch (e) { toast(t('album.createFail'), 'err'); }
});

function updateSelectionUI() {
  const btn = $('create-share-btn');
  // Folder-chooser mode: the "selection" is simply the folder currently open.
  if (state.pickerMode === 'configDir') {
    $('selection-name').textContent = state.cwd || '/';
    btn.disabled = false;
    return;
  }
  const sel = state.selections;
  if (sel.length === 0) {
    $('selection-name').textContent = '—';
    btn.disabled = true;
  } else if (sel.length === 1) {
    $('selection-name').textContent = sel[0].name + t(sel[0].isDir ? 'pk.folderSuffix' : 'pk.fileSuffix');
    btn.disabled = false;
  } else {
    $('selection-name').textContent = t('pk.selectedN', { n: sel.length });
    btn.disabled = false;
  }
}

async function browse(pathStr, fallbackToRoot) {
  try {
    const data = await api('GET', '/api/browse?path=' + encodeURIComponent(pathStr || '/'));
    state.cwd = data.cwd || '/';
    $('root-label').textContent = data.cwd || '/';
    renderBreadcrumbs(data);
    renderBrowser(data);
    if (state.pickerMode === 'configDir') updateSelectionUI(); // reflect the current folder
  } catch (e) {
    if (e.message === 'not-authenticated') return;
    // A stale default folder shouldn't dead-end the picker: retry once at the root.
    if (fallbackToRoot && (pathStr || '/') !== '/') { browse('/', false); return; }
    toast(e.data && e.data.error === 'host-inaccessible' ? t('pk.hostInaccessible') : t('pk.navFail'), 'err');
  }
}

function renderBreadcrumbs(data) {
  const box = $('breadcrumbs');
  box.textContent = '';
  const rootLink = el('a', { text: '🖥 /' });
  rootLink.addEventListener('click', () => browse('/'));
  box.appendChild(rootLink);

  const cwd = data.cwd || '/';
  if (cwd !== '/') {
    let acc = '';
    cwd.split('/').filter(Boolean).forEach((p) => {
      acc = acc + '/' + p;
      const target = acc;
      box.appendChild(el('span', { class: 'crumb-sep', text: '/' }));
      const a = el('a', { text: p });
      a.addEventListener('click', () => browse(target));
      box.appendChild(a);
    });
  }
}

function renderBrowser(data) {
  const list = $('browser-list');
  list.textContent = '';
  // The parent-folder control must not consume one of the ten requested visible
  // file rows. CSS adds one row of height whenever this marker is present.
  list.classList.toggle('has-parent', data.parent !== null && data.parent !== undefined);
  const cwd = String(data.cwd || state.cwd || '/');
  // Shift ranges are meaningful only inside the folder that established the anchor.
  if (state.pickerRangeCwd !== cwd) {
    state.pickerRangeAnchor = null;
    state.pickerRangeCwd = cwd;
  }

  if (data.parent !== null && data.parent !== undefined) {
    const up = el('div', { class: 'row' });
    up.appendChild(el('span', { class: 'ico', text: '⬆' }));
    up.appendChild(el('span', { class: 'name', text: t('pk.parent') }));
    up.addEventListener('click', () => browse(data.parent));
    list.appendChild(up);
  }

  if (!data.entries.length) {
    list.appendChild(el('div', { class: 'empty', text: t('pk.emptyFolder') }));
    return;
  }

  data.entries.forEach((entry, entryIndex) => {
    const row = el('div', { class: 'row' });
    row.dataset.pickerIndex = String(entryIndex);
    row.appendChild(el('span', { class: 'ico', text: entry.isDir ? '📁' : '📄' }));
    row.appendChild(el('span', { class: 'name', text: entry.name }));

    if (entry.isDir) {
      row.appendChild(el('span', { class: 'open', text: t('pk.open') }));
    } else {
      row.appendChild(el('span', { class: 'size', text: formatBytes(entry.size) }));
      if (isPreviewableFile(entry.name)) {
        const previewBtn = el('span', { class: 'preview', text: t('pk.preview') });
        previewBtn.addEventListener('click', (ev) => {
          ev.stopPropagation();
          openPreview(entry);
        });
        row.appendChild(previewBtn);
      }
    }

    // Reflect an already-picked item when returning to its folder (selection
    // persists across navigation, so you can gather items from several folders).
    if (state.pickerMode !== 'configDir' && state.selections.some((x) => x.path === entry.path)) {
      row.classList.add('selected');
    }

    row.addEventListener('click', (ev) => {
      if (entry.isDir && ev.target.classList.contains('open')) {
        browse(entry.path);
        return;
      }
      // Folder-chooser mode: rows only navigate (the current folder is the pick).
      if (state.pickerMode === 'configDir') {
        if (entry.isDir) browse(entry.path);
        return;
      }
      if (ev.shiftKey && state.pickerRangeAnchor && state.pickerRangeCwd === cwd) {
        const anchorIndex = data.entries.findIndex((x) => x.path === state.pickerRangeAnchor);
        if (anchorIndex !== -1) {
          selectPickerRange(data.entries, anchorIndex, entryIndex, list);
          return;
        }
      }
      toggleItem(entry, row);
      state.pickerRangeAnchor = entry.path;
      state.pickerRangeCwd = cwd;
    });
    if (entry.isDir) row.addEventListener('dblclick', () => browse(entry.path));
    list.appendChild(row);
  });
}

function setPickerItemSelected(entry, selected, row) {
  const i = state.selections.findIndex((x) => x.path === entry.path);
  if (selected && i === -1) state.selections.push({ path: entry.path, name: entry.name, isDir: entry.isDir });
  if (!selected && i !== -1) state.selections.splice(i, 1);
  if (row) row.classList.toggle('selected', selected);
}

// Windows/Explorer-style range selection: after selecting one entry, Shift+click
// another entry selects the entire contiguous range. Existing selections in other
// folders are preserved, so range selection composes with Direct-Xfer's picker.
function selectPickerRange(entries, fromIndex, toIndex, list) {
  const lo = Math.min(fromIndex, toIndex), hi = Math.max(fromIndex, toIndex);
  for (let i = lo; i <= hi; i++) {
    const entry = entries[i];
    const row = list && list.querySelector(`[data-picker-index="${i}"]`);
    setPickerItemSelected(entry, true, row);
  }
  updateSelectionUI();
}

// Multi-select: clicking a row toggles it in/out of state.selections.
function toggleItem(entry, row) {
  const selected = !state.selections.some((x) => x.path === entry.path);
  setPickerItemSelected(entry, selected, row);
  updateSelectionUI();
}

function dlpRuleLabel(type){const key='dlp.rule.'+String(type||'');const v=t(key);return v===key?String(type||'DLP').replace(/-/g,' '):v;}
function dlpRuleReason(f){const key='dlp.reason.'+String(f&&f.type||'');const v=t(key);return v===key?String(f&&f.detail||'—'):v;}
function dlpFindingLines(d,limit){return (d&&Array.isArray(d.findings)?d.findings:[]).slice(0,limit||5).map((f)=>`${dlpRuleLabel(f.type)} · ${f.file||'—'} · ${f.sample||'—'} · ${dlpRuleReason(f)}`);}
function closeDlpDetails(){const o=$('dlp-details-overlay');if(o)o.classList.add('hidden');}
function showDlpDetails(d,title){const o=$('dlp-details-overlay'),list=$('dlp-details-list'),sum=$('dlp-details-summary'),head=$('dlp-details-title');if(!o||!list)return;if(head)head.textContent=title||t('dlp.detailsTitle');if(sum)sum.textContent=t('dlp.detailsSummary',{n:d&&d.count||0,level:d&&d.highest||'—'});list.textContent='';const findings=d&&Array.isArray(d.findings)?d.findings:[];if(!findings.length){list.appendChild(el('div',{class:'empty',text:t('dlp.detailsNone')}));}else findings.forEach((f)=>{const row=el('div',{class:'dlp-detail-row'});row.appendChild(el('strong',{text:dlpRuleLabel(f.type)}));const grid=el('div',{class:'dlp-detail-grid'});[[t('dlp.file'),f.file||'—'],[t('dlp.sample'),f.sample||'—'],[t('dlp.reason'),dlpRuleReason(f)]].forEach(([a,b])=>{const cell=el('div',{class:'dlp-detail-cell'});cell.append(el('span',{class:'muted sm',text:a}),el('span',{text:b}));grid.appendChild(cell);});row.appendChild(grid);list.appendChild(row);});o.classList.remove('hidden');}
if($('dlp-details-close'))$('dlp-details-close').addEventListener('click',closeDlpDetails);
if($('dlp-details-overlay'))$('dlp-details-overlay').addEventListener('click',(e)=>{if(e.target===$('dlp-details-overlay'))closeDlpDetails();});

let activeDirectXferConfirmCancel = null;
function confirmDirectXferAction(message, options) {
  options = options || {};
  if (typeof activeDirectXferConfirmCancel === 'function') activeDirectXferConfirmCancel();
  return new Promise((resolve) => {
    const previousFocus = document.activeElement;
    const overlay = el('div', { class:'overlay', attrs:{ id:'dx-confirm-overlay' } });
    const modal = el('div', { class:'modal', attrs:{ role:'dialog', 'aria-modal':'true', 'aria-labelledby':'dx-confirm-title' } });
    const head = el('div', { class:'modal-head' });
    const title = el('h3', { text:options.title || t('confirm.title'), attrs:{ id:'dx-confirm-title' } });
    const close = el('button', { class:'icon-btn', text:'✕', attrs:{ type:'button', 'aria-label':t('confirm.cancel') } });
    head.append(title, close);
    const text = el('p', { class:'muted sm', text:String(message || '') });
    text.style.whiteSpace = 'pre-line';
    const actions = el('div', { class:'modal-actions' });
    const cancel = el('button', { class:'btn ghost', text:options.cancelText || t('confirm.cancel'), attrs:{ type:'button' } });
    const confirm = el('button', { class:options.danger ? 'btn danger' : 'btn primary', text:options.confirmText || t('confirm.title'), attrs:{ type:'button' } });
    actions.append(cancel, confirm); modal.append(head, text, actions); overlay.appendChild(modal); document.body.appendChild(overlay);
    let settled = false;
    let cancelCurrent = null;
    const finish = (approved) => {
      if (settled) return;
      settled = true;
      document.removeEventListener('keydown', onKey, true);
      if (activeDirectXferConfirmCancel === cancelCurrent) activeDirectXferConfirmCancel = null;
      overlay.remove();
      try { if (previousFocus && typeof previousFocus.focus === 'function') previousFocus.focus(); } catch (_) {}
      resolve(approved);
    };
    cancelCurrent = () => finish(false);
    activeDirectXferConfirmCancel = cancelCurrent;
    const onKey = (event) => {
      if (event.key !== 'Escape') return;
      event.preventDefault(); event.stopPropagation(); finish(false);
    };
    close.addEventListener('click', cancelCurrent);
    cancel.addEventListener('click', cancelCurrent);
    confirm.addEventListener('click', () => finish(true));
    overlay.addEventListener('click', (event) => { if (event.target === overlay) finish(false); });
    document.addEventListener('keydown', onKey, true);
    setTimeout(() => { try { confirm.focus(); } catch (_) {} }, 0);
  });
}

function dlpWarningParts(data) {
  const d = data && data.dlp;
  if (!d || (!d.count && !d.incomplete && !d.ocrUnavailable && !d.filesSkipped && !d.ocrErrors && !d.scanErrors && !d.incompleteEntries && !d.truncated)) return null;
  const onlyOcrUnavailable = d.ocrUnavailable && !d.count && !d.filesSkipped && !d.ocrErrors && !d.scanErrors && !d.incompleteEntries && !d.truncated;
  const parts = [];
  if (d.count) parts.push(t('dlp.warningConfirm', { n:d.count || 0, level:d.highest || '—', files:d.filesScanned || 0 }));
  if (onlyOcrUnavailable) parts.push(t('dlp.ocrUnavailableConfirm'));
  else if (d.incomplete || d.filesSkipped || d.ocrErrors || d.scanErrors || d.incompleteEntries || d.truncated || d.ocrUnavailable) {
    parts.push(t('dlp.incompleteConfirm', { skipped:d.filesSkipped || 0, ocr:d.ocrErrors || 0, scan:d.scanErrors || 0, archive:d.incompleteEntries || 0 }));
    if ((d.filesSkipped || 0) > 0 && Number(d.maxFileMB) > 0) parts.push(t('dlp.skippedSizeHint', { limit:Number(d.maxFileMB).toFixed(Number(d.maxFileMB) % 1 ? 1 : 0) }));
  }
  parts.push(t('dlp.warningQuestion'));
  return { d, text:parts.join('\n\n') };
}
function confirmDlpWarning(data) {
  const warning = dlpWarningParts(data);
  if (!warning) return Promise.resolve(false);
  return new Promise((resolve) => {
    const previousFocus = document.activeElement;
    const overlay = el('div', { class:'overlay', attrs:{ id:'dlp-warning-overlay' } });
    const modal = el('div', { class:'modal', attrs:{ role:'dialog', 'aria-modal':'true', 'aria-labelledby':'dlp-warning-title' } });
    const head = el('div', { class:'modal-head' });
    const title = el('h3', { text:t(warning.d.count ? 'dlp.warningTitle' : 'dlp.incompleteTitle'), attrs:{ id:'dlp-warning-title' } });
    const close = el('button', { class:'icon-btn', text:'✕', attrs:{ type:'button', 'aria-label':t('dlp.cancelWarning') } });
    head.append(title, close);
    const message = el('p', { class:'muted sm', text:warning.text });
    message.style.whiteSpace = 'pre-line';
    modal.append(head, message);
    const findings = warning.d && Array.isArray(warning.d.findings) ? warning.d.findings.slice(0, 5) : [];
    if (findings.length) {
      const list = el('div', { class:'dlp-details-list' });
      findings.forEach((f) => {
        const row = el('div', { class:'dlp-detail-row' });
        row.appendChild(el('strong', { text:dlpRuleLabel(f.type) }));
        const grid = el('div', { class:'dlp-detail-grid' });
        [[t('dlp.file'), f.file || '—'], [t('dlp.sample'), f.sample || '—'], [t('dlp.reason'), dlpRuleReason(f)]].forEach(([label, value]) => {
          const cell = el('div', { class:'dlp-detail-cell' });
          cell.append(el('span', { class:'muted sm', text:label }), el('span', { text:value }));
          grid.appendChild(cell);
        });
        row.appendChild(grid); list.appendChild(row);
      });
      modal.appendChild(list);
    }
    const actions = el('div', { class:'modal-actions' });
    const cancel = el('button', { class:'btn ghost', text:t('dlp.cancelWarning'), attrs:{ type:'button' } });
    const proceed = el('button', { class:'btn primary', text:t('dlp.publishAnyway'), attrs:{ type:'button' } });
    actions.append(cancel, proceed); modal.appendChild(actions); overlay.appendChild(modal); document.body.appendChild(overlay);
    let settled = false;
    const finish = (approved) => {
      if (settled) return; settled = true;
      document.removeEventListener('keydown', onKey);
      overlay.remove();
      try { if (previousFocus && typeof previousFocus.focus === 'function') previousFocus.focus(); } catch (_) {}
      resolve(approved);
    };
    const onKey = (event) => { if (event.key === 'Escape') { event.preventDefault(); finish(false); } };
    close.addEventListener('click', () => finish(false)); cancel.addEventListener('click', () => finish(false)); proceed.addEventListener('click', () => finish(true));
    overlay.addEventListener('click', (event) => { if (event.target === overlay) finish(false); });
    document.addEventListener('keydown', onKey);
    setTimeout(() => { try { proceed.focus(); } catch (_) {} }, 0);
  });
}
function dlpCancelledError(data) { const err = new Error('dlp-cancelled'); err.code = 'dlp-cancelled'; err.data = data || null; err.userCancelled = true; return err; }
function isDlpCancelled(error) { return !!(error && (error.userCancelled === true || error.code === 'dlp-cancelled' || error.message === 'dlp-cancelled')); }
async function apiWithDlpOverride(method, url, payload) {
  try { return await api(method, url, payload); }
  catch (e) {
    if (e && e.data && e.data.error === 'dlp-warning') {
      if (await confirmDlpWarning(e.data)) return api(method, url, Object.assign({}, payload || {}, { dlpOverride:true }));
      throw dlpCancelledError(e.data);
    }
    if(e&&e.data&&['dlp-blocked','dlp-quarantined','dlp-quarantine-failed'].includes(e.data.error)&&e.data.dlp)showDlpDetails(e.data.dlp,t('dlp.detailsTitle'));
    throw e;
  }
}
function dlpErrorMessage(error) {
  const code = error && error.data && error.data.error;
  if (code === 'dlp-blocked') return t('dlp.blocked');
  if (code === 'dlp-quarantined') return t('dlp.quarantined');
  if (code === 'dlp-quarantine-failed') return t('dlp.quarantineFailed');
  return '';
}

$('create-share-btn').addEventListener('click', async () => {
  // Folder chooser for the "default folder" config field: take the current folder.
  if (state.pickerMode === 'configDir') {
    if ($('cfg-default-dir')) $('cfg-default-dir').value = state.cwd || '';
    closePicker();
    return;
  }
  if (!state.selections.length) return;
  const paths = state.selections.map((x) => x.path);
  // Photos tab — create direct image links from the selected image files.
  if (state.pickerMode === 'photos') {
    await createPhotos(paths);
    return;
  }
  if (state.pickerMode === 'addTo') {
    try {
      await apiWithDlpOverride('POST', '/api/shares/' + encodeURIComponent(state.addToShareId) + '/items', { paths });
      toast(t('sh.added'), 'ok');
      closePicker();
      refreshShares();
    } catch (e) {
      if (isDlpCancelled(e)) { toast(t('dlp.cancelled'),'warn'); return; }
      toast(dlpErrorMessage(e) || t('sh.addFail', { error: (e.data && e.data.error) || e.message }), 'err');
    }
    return;
  }
  // Warn if a selected path is already shared by an active link.
  const dupes = (state.allShares || []).filter((sh) => sh.active && paths.includes(sh.hostPath)).map((sh) => sh.name);
  if (dupes.length && !confirm(t('sh.dupWarn', { names: dupes.slice(0, 5).join(', ') }))) return;
  const expiry = parseInt($('opt-expiry').value, 10) || 0;
  const maxdl = parseInt($('opt-maxdl').value, 10) || 0;
  const password = $('opt-password').value;
  // Password required by default (Configuration): block creation without one.
  if ($('opt-password').required && !password) {
    toast(t('cfg.pwRequired'), 'err');
    $('opt-password').focus();
    return;
  }
  const rateRaw = String($('opt-rate').value || '').trim();
  const rateKBps = rateRaw === '' ? 0 : Number(rateRaw);
  if (!Number.isFinite(rateKBps) || !Number.isInteger(rateKBps) || rateKBps < 0) {
    toast(t('sh.addFail', { error:'invalid-rate' }), 'err');
    $('opt-rate').focus();
    return;
  }
  const allowZip = $('opt-allowzip').checked;
  const noPreview = !$('opt-preview').checked;
  const burnAfterDownload = $('opt-burn').checked;
  const color = $('opt-color') ? $('opt-color').value.trim() : '';
  const tags = $('opt-tags') ? $('opt-tags').value.split(',').map((x) => x.trim()).filter(Boolean) : [];
  const descriptionMd = $('opt-description') ? $('opt-description').value : '';
  const expiryReminderHours = $('opt-reminder') && $('opt-reminder').value !== '' ? Number($('opt-reminder').value) : null;
  const firstUseExpirySeconds = $('opt-firstuse') ? Math.max(0, Math.round((parseFloat($('opt-firstuse').value) || 0) * 3600)) : 0;
  const inactiveExpirySeconds = $('opt-inactive') ? Math.max(0, Math.round((parseFloat($('opt-inactive').value) || 0) * 86400)) : 0;
  const note = $('opt-note') ? $('opt-note').value : '';
  const startsAt = startsAtMs('opt-startsat');
  try {
    const resp = await apiWithDlpOverride('POST', '/api/shares', {
      paths,
      expiresInSeconds: expiry,
      expiresAt: expireAtMs('opt-expireat') || undefined, // absolute date wins when set
      startsAt,
      maxDownloads: maxdl,
      maxVisitors: parseInt($('opt-maxvisitors').value, 10) || 0,
      notifyDownloadThreshold: parseInt($('opt-dlthreshold') && $('opt-dlthreshold').value, 10) || 0, // download-goal alert
      maxDownloadsPerIp: parseInt($('opt-maxdlperip').value, 10) || 0,
      maxBytesServed: Math.round((parseFloat($('opt-maxbytesserved') && $('opt-maxbytesserved').value) || 0) * 1073741824), // (GB→bytes)
      emoji: $('opt-emoji') ? $('opt-emoji').value : '',
      password,
      pwHint: $('opt-pwhint') ? $('opt-pwhint').value : '',
      rateKBps,
      allowZip,
      noPreview,
      burnAfterDownload,
      requestAccess: $('opt-requestaccess') ? $('opt-requestaccess').checked : false,
      allowFeedback: $('opt-feedback') ? $('opt-feedback').checked : false,
      color, tags, descriptionMd, expiryReminderHours, firstUseExpirySeconds, inactiveExpirySeconds,
      note,
    });
    if (password && resp && resp.share) rememberLinkPassword(resp.share.url, password);
    toast(t('sh.created2'), 'ok');
    $('opt-maxdl').value = '';
    $('opt-maxvisitors').value = '';
    if ($('opt-dlthreshold')) $('opt-dlthreshold').value = '';
    if ($('opt-maxdlperip')) $('opt-maxdlperip').value = '';
    if ($('opt-pwhint')) $('opt-pwhint').value = '';
    $('opt-password').value = '';
    $('opt-rate').value = '';
    $('opt-startsat').value = '';
    if ($('opt-expireat')) $('opt-expireat').value = '';
    $('opt-allowzip').checked = true;
    $('opt-preview').checked = true;
    $('opt-burn').checked = false;
    if ($('opt-requestaccess')) $('opt-requestaccess').checked = false;
    if ($('opt-feedback')) $('opt-feedback').checked = false;
    if ($('opt-color')) $('opt-color').value = '';
    if ($('opt-tags')) $('opt-tags').value = '';
    if ($('opt-description')) $('opt-description').value = '';
    if ($('opt-reminder')) $('opt-reminder').value = '';
    if ($('opt-firstuse')) $('opt-firstuse').value = '';
    if ($('opt-inactive')) $('opt-inactive').value = '';
    if ($('opt-note')) $('opt-note').value = '';
    $('opt-password').required = false;
    closePicker();
    if (resp && resp.share) showCreatedShareLink(resp.share);
    refreshShares();
    // Auto-open the QR code when the default is enabled (Configuration).
    if (state.settings && state.settings.defaultShowQr && resp && resp.share && resp.share.url) {
      openQr(resp.share);
    }
  } catch (e) {
    if (isDlpCancelled(e)) { toast(t('dlp.cancelled'),'warn'); return; }
    toast(dlpErrorMessage(e) || t('sh.createFail', { error: (e.data && e.data.error) || e.message }), 'err');
  }
});

// ------------------------------------------------------------------
// Metadata (version / year) for the footer
// ------------------------------------------------------------------
let createdShareBannerTimer = null;
function hideCreatedShareLink() {
  if (createdShareBannerTimer) {
    clearTimeout(createdShareBannerTimer);
    createdShareBannerTimer = null;
  }
  const banner = $('share-created-banner'), urlNode = $('share-created-url');
  if (banner) {
    banner.classList.add('hidden');
    delete banner.dataset.url;
  }
  if (urlNode) urlNode.textContent = '';
}
function showCreatedShareLink(share) {
  const banner=$('share-created-banner'), urlNode=$('share-created-url');
  if(!banner||!urlNode||!share||!share.url)return;
  if (createdShareBannerTimer) clearTimeout(createdShareBannerTimer);
  urlNode.textContent=share.url; banner.dataset.url=share.url; banner.classList.remove('hidden');
  createdShareBannerTimer = setTimeout(hideCreatedShareLink, 60 * 1000);
  try{banner.scrollIntoView({block:'nearest',behavior:'smooth'});}catch(_){}
}
if($('share-created-copy'))$('share-created-copy').addEventListener('click',()=>{const banner=$('share-created-banner');const url=banner&&banner.dataset.url;if(url)copy(url);});
if($('share-created-close'))$('share-created-close').addEventListener('click',hideCreatedShareLink);

async function loadMeta() {
  try {
    const r = await fetchWithTimeout('/api/meta', { credentials: 'same-origin' }, 10000);
    const m = await r.json();
    state.meta = m; // kept for the About dialog (version, release date)
    document.querySelectorAll('.app-version').forEach((e) => {
      e.textContent = m.version ? 'v' + m.version : '';
    });
    document.querySelectorAll('.app-year').forEach((e) => {
      e.textContent = m.year || '';
    });
    const note = document.getElementById('update-notice');
    if (note) {
      if (m.update && m.update.available && m.update.latest) {
        note.textContent = t('update.available', { v: m.update.latest });
        if (m.update.url) note.href = m.update.url;
        note.classList.remove('hidden');
      } else {
        note.classList.add('hidden');
      }
    }
    // Login-page storage warning: reception / images folders still on the
    // container's ephemeral filesystem (default, un-mapped volume). The message
    // text itself is localized via data-i18n; here we only toggle visibility.
    const sw = document.getElementById('setup-warning');
    if (sw) {
      const inbox = !!(m.setup && m.setup.inboxUnconfigured);
      const images = !!(m.setup && m.setup.imagesUnconfigured);
      const inboxEl = document.getElementById('setup-warn-inbox');
      const imagesEl = document.getElementById('setup-warn-images');
      if (inboxEl) inboxEl.classList.toggle('hidden', !inbox);
      if (imagesEl) imagesEl.classList.toggle('hidden', !images);
      sw.classList.toggle('hidden', !(inbox || images));
    }
  } catch (_) {}
}

// ------------------------------------------------------------------
// Lifecycle
// ------------------------------------------------------------------
async function init() {
  // Authenticated data must not wait on network diagnostics: a slow public-IP or
  // interface probe must never delay the links list, notifications or restored URL.
  startNotificationsPolling();
  startPolling();
  maybeOpenAdminSubpageFromUrl(); // reopen /images or /dashboards after sign-in/reload
  void loadNetwork();
}

document.addEventListener('visibilitychange', () => {
  if (document.hidden) stopPolling();
  else if (isLoggedIn()) {
    startPolling();
    // Notification polling intentionally sleeps in hidden tabs. Refresh once on
    // return so the badge catches up immediately instead of waiting up to 4 s.
    refreshNotifications(true);
  }
});

// Restore theme, filters, periods and view modes before the first render.
setTheme(getTheme());
applyUiPreferencesToControls();
// Apply the language + load the version, then check the session.
setLang(state.lang);
initPasswordTools(); // password generator + strength meter
loadMeta();
setTimeout(loadMeta, 12000); // re-check so a freshly-started server surfaces an update

(async function bootstrap() {
  try {
    const s = await fetchWithTimeout('/api/session', { credentials: 'same-origin' }, 12000);
    if (s.ok) {
      const data = await s.json();
      state.authEpoch += 1;
      state.csrf = data.csrf;
      state.username = data.username;
      state.role = data.role;
      enterApp(data.mustChangePassword);
      return;
    }
  } catch (_) {}
  showLogin();
})();

// ==================================================================
// End-to-end encrypted shares & reception links (browser-side crypto)
// dxcrypto.js is loaded before app.js; nothing here sends a key/passphrase
// to the server. The server only ever receives opaque ciphertext.
// ==================================================================
(function () {
  var C = window.DXCrypto;
  var hasCrypto = !!(C && C.available);

  // Without a secure context (HTTPS/localhost) WebCrypto is unavailable, so the
  // encryption controls are hidden entirely rather than shown-but-broken.
  function hideEl(id) { var el = $(id); if (el) el.classList.add('hidden'); }
  if (!hasCrypto) {
    hideEl('new-enc-btn');
    hideEl('new-secret-btn');
    hideEl('ib-encrypt-row');
    hideEl('ib-enc-mode-row');
  }

  // ---- shared "encrypted link ready" result modal ----
  function showEncLink(name, url, note) {
    $('enclink-name').textContent = name || '';
    $('enclink-url').textContent = url;
    $('enclink-note').textContent = note || '';
    $('enclink-overlay').dataset.url = url;
    $('enclink-overlay').classList.remove('hidden');
  }
  function closeEncLink() { $('enclink-overlay').classList.add('hidden'); }
  function copyText(txt) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(txt).then(
        function () { toast(t('sh.copied'), 'ok'); },
        function () { fallbackCopy(txt); });
    } else { fallbackCopy(txt); }
  }
  function fallbackCopy(txt) {
    var ta = document.createElement('textarea');
    ta.value = txt; document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); toast(t('sh.copied'), 'ok'); }
    catch (_) { toast(t('sh.copyFail'), 'err'); }
    document.body.removeChild(ta);
  }
  if ($('enclink-close')) $('enclink-close').addEventListener('click', closeEncLink);
  if ($('enclink-done')) $('enclink-done').addEventListener('click', closeEncLink);
  if ($('enclink-copy')) $('enclink-copy').addEventListener('click', function () {
    copyText($('enclink-overlay').dataset.url || $('enclink-url').textContent);
  });
  if ($('enclink-overlay')) $('enclink-overlay').addEventListener('click', function (e) {
    if (e.target === $('enclink-overlay')) closeEncLink();
  });

  function withKey(url, rawKey) { return url + '#k=' + C.b64urlEncode(rawKey); }

  // ---------------- Encrypted download share ----------------
  function openEncModal() {
    $('enc-file').value = '';
    $('enc-label').value = '';
    $('enc-mode').value = 'key';
    $('enc-pass').value = '';
    $('enc-expiry').value = '0';
    $('enc-startsat').value = '';
    $('enc-maxdl').value = '';
    $('enc-pass-row').classList.add('hidden');
    $('enc-progwrap').classList.add('hidden');
    $('enc-prog').value = 0;
    $('enc-error').classList.add('hidden');
    if (!hasCrypto) { $('enc-file').disabled = true; $('enc-submit').disabled = true; encError(t('dec.noCrypto')); }
    else { $('enc-file').disabled = false; $('enc-submit').disabled = false; }
    $('enc-overlay').classList.remove('hidden');
    $('enc-file').focus();
  }
  function closeEncModal() { $('enc-overlay').classList.add('hidden'); }
  function encModeChanged() {
    $('enc-pass-row').classList.toggle('hidden', $('enc-mode').value !== 'pass');
  }
  function encError(msg) { var e = $('enc-error'); e.textContent = msg; e.classList.remove('hidden'); }

  if ($('new-enc-btn')) $('new-enc-btn').addEventListener('click', openEncModal);
  if ($('enc-close')) $('enc-close').addEventListener('click', closeEncModal);
  if ($('enc-cancel')) $('enc-cancel').addEventListener('click', closeEncModal);
  if ($('enc-mode')) $('enc-mode').addEventListener('change', encModeChanged);
  if ($('enc-overlay')) $('enc-overlay').addEventListener('click', function (e) {
    if (e.target === $('enc-overlay')) closeEncModal();
  });
  if ($('enc-file')) $('enc-file').addEventListener('change', function () {
    if (!$('enc-label').value && $('enc-file').files[0]) $('enc-label').value = $('enc-file').files[0].name;
  });

  if ($('enc-form')) $('enc-form').addEventListener('submit', function (e) {
    e.preventDefault();
    $('enc-error').classList.add('hidden');
    var file = $('enc-file').files[0];
    if (!file) { encError(t('enc.needFile')); return; }
    var mode = $('enc-mode').value === 'pass' ? 'pass' : 'key';
    var pass = $('enc-pass').value;
    if (mode === 'pass' && !pass) { encError(t('enc.needPass')); return; }
    var label = ($('enc-label').value || file.name || 'Encrypted file').slice(0, 200);
    var expiry = parseInt($('enc-expiry').value, 10) || 0;
    var maxdl = parseInt($('enc-maxdl').value, 10) || 0;
    var startsAt = startsAtMs('enc-startsat');

    var submit = $('enc-submit');
    submit.disabled = true;
    $('enc-progwrap').classList.remove('hidden');
    $('enc-progtext').textContent = t('enc.encrypting');
    $('enc-prog').value = 0;

    var rawKey = null, salt = null, keyPromise;
    if (mode === 'pass') { salt = C.randomSalt(); keyPromise = C.deriveKey(pass, salt); }
    else { rawKey = C.genRawKey(); keyPromise = C.importRawKey(rawKey); }

    keyPromise.then(function (key) {
      return C.encryptFile(file, mode, {
        key: key, salt: salt,
        onProgress: function (f) { $('enc-prog').value = Math.max(0, Math.min(1, f)); },
      });
    }).then(function (blob) {
      $('enc-progtext').textContent = t('enc.uploading');
      var qs = '?mode=' + mode +
        '&label=' + encodeURIComponent(label) +
        '&expiresInSeconds=' + expiry +
        '&startsAt=' + startsAt +
        '&maxDownloads=' + maxdl;
      var headers = { 'Content-Type': 'application/octet-stream' };
      if (state.csrf) headers['X-CSRF-Token'] = state.csrf;
      return fetch('/api/enc-share' + qs, {
        method: 'POST', credentials: 'same-origin', headers: headers, body: blob,
      });
    }).then(function (res) {
      if (res.status === 401) { showLogin(); throw new Error('auth'); }
      if (!res.ok) throw new Error('http');
      return res.json();
    }).then(function (data) {
      var url = data.share.url;
      var full = (mode === 'key') ? withKey(url, rawKey) : url;
      submit.disabled = false;
      closeEncModal();
      toast(t('enc.created'), 'ok');
      refreshShares();
      showEncLink(label, full, mode === 'key' ? t('enc.noteKey') : t('enc.notePass'));
    }).catch(function () {
      submit.disabled = false;
      $('enc-progwrap').classList.add('hidden');
      encError(t('enc.createFail'));
    });
  });

  // ---------------- Burn-after-read secret note ----------------
  function openSecretModal() {
    if (!hasCrypto) { toast(t('enc.createFail'), 'err'); return; }
    $('secret-text').value = '';
    $('secret-mode').value = 'key';
    $('secret-expiry').value = '0';
    $('secret-pass-in').value = '';
    $('secret-pass-row').classList.add('hidden');
    $('secret-error').classList.add('hidden');
    $('secret-overlay').classList.remove('hidden');
    $('secret-text').focus();
  }
  function closeSecretModal() { $('secret-overlay').classList.add('hidden'); }
  function secretError(msg) { var e = $('secret-error'); e.textContent = msg; e.classList.remove('hidden'); }
  if ($('new-secret-btn')) $('new-secret-btn').addEventListener('click', openSecretModal);
  if ($('secret-close')) $('secret-close').addEventListener('click', closeSecretModal);
  if ($('secret-cancel')) $('secret-cancel').addEventListener('click', closeSecretModal);
  if ($('secret-overlay')) $('secret-overlay').addEventListener('click', function (e) {
    if (e.target === $('secret-overlay')) closeSecretModal();
  });
  if ($('secret-mode')) $('secret-mode').addEventListener('change', function () {
    $('secret-pass-row').classList.toggle('hidden', $('secret-mode').value !== 'pass');
  });
  if ($('secret-form')) $('secret-form').addEventListener('submit', function (e) {
    e.preventDefault();
    var text = $('secret-text').value;
    if (!text) { secretError(t('secret.needText')); return; }
    var mode = $('secret-mode').value === 'pass' ? 'pass' : 'key';
    var pass = $('secret-pass-in').value;
    if (mode === 'pass' && !pass) { secretError(t('enc.needPass')); return; }
    var expiry = parseInt($('secret-expiry').value, 10) || 0;
    var submit = $('secret-submit');
    submit.disabled = true;
    // Encrypt the text as a DXE container (reusing the file crypto) in-browser.
    var blob = new Blob([text], { type: 'text/plain' });
    var file = new File([blob], 'secret.txt', { type: 'text/plain' });
    var rawKey = null, salt = null, keyPromise;
    if (mode === 'pass') { salt = C.randomSalt(); keyPromise = C.deriveKey(pass, salt); }
    else { rawKey = C.genRawKey(); keyPromise = C.importRawKey(rawKey); }
    keyPromise.then(function (key) {
      return C.encryptFile(file, mode, { key: key, salt: salt });
    }).then(function (ct) {
      var headers = { 'Content-Type': 'application/octet-stream' };
      if (state.csrf) headers['X-CSRF-Token'] = state.csrf;
      return fetch('/api/secret?mode=' + mode + '&expiresInSeconds=' + expiry, {
        method: 'POST', credentials: 'same-origin', headers: headers, body: ct,
      });
    }).then(function (res) {
      if (res.status === 401) { showLogin(); throw new Error('auth'); }
      if (!res.ok) throw new Error('http');
      return res.json();
    }).then(function (data) {
      var url = data.url || (location.origin + data.path);
      var full = (mode === 'key') ? withKey(url, rawKey) : url;
      submit.disabled = false;
      closeSecretModal();
      toast(t('secret.created'), 'ok');
      showEncLink(t('secret.title'), full, mode === 'key' ? t('secret.noteKey') : t('secret.notePass'));
    }).catch(function () {
      submit.disabled = false;
      secretError(t('secret.createFail'));
    });
  });

  // ---------------- Encrypted reception link ----------------
  function inboxEncChanged() {
    var on = $('ib-encrypt') && $('ib-encrypt').checked;
    if ($('ib-enc-mode-row')) $('ib-enc-mode-row').classList.toggle('hidden', !on);
  }
  if ($('ib-encrypt')) $('ib-encrypt').addEventListener('change', inboxEncChanged);

  // Hook called by the inbox-form submit handler.
  window.DXInboxEnc = {
    // Returns { payloadExtra, finalize(url,name) } when encrypting, else null.
    plan: function () {
      if (!$('ib-encrypt') || !$('ib-encrypt').checked) return null;
      if (!hasCrypto) { toast(t('enc.createFail'), 'err'); return null; }
      var mode = ($('ib-enc-mode') && $('ib-enc-mode').value === 'pass') ? 'pass' : 'key';
      var rawKey = mode === 'key' ? C.genRawKey() : null;
      return {
        payloadExtra: { encrypted: true, encMode: mode },
        finalize: function (shareUrl, name) {
          var full = mode === 'key' ? withKey(shareUrl, rawKey) : shareUrl;
          showEncLink(name, full, mode === 'key' ? t('enc.inboxLinkNote') : t('enc.notePass'));
        },
      };
    },
    reset: function () {
      if ($('ib-encrypt')) $('ib-encrypt').checked = false;
      if ($('ib-enc-mode')) $('ib-enc-mode').value = 'key';
      inboxEncChanged();
    },
  };

})();

// ==================================================================
// Decrypt a received .dxe file (browser-side, in the user menu)
// The ciphertext is read locally; the key/passphrase never leaves the page.
// ==================================================================
(function () {
  var C = window.DXCrypto;
  var hasCrypto = !!(C && C.available);
  var decFile = null;  // the selected .dxe File (a Blob, read in chunks — not fully loaded)
  var decMode = null;  // 'key' | 'pass'

  // No secure context → no WebCrypto → hide the "Decrypt a .dxe file" menu item.
  if (!hasCrypto) { var db = $('decrypt-btn'); if (db) db.classList.add('hidden'); }

  function decErr(msg) { var e = $('dec-error'); e.textContent = msg || ''; if (msg) e.classList.remove('hidden'); else e.classList.add('hidden'); }
  function openDecModal() {
    decFile = null; decMode = null;
    $('dec-file').value = '';
    $('dec-key').value = '';
    $('dec-pass').value = '';
    $('dec-key-row').classList.add('hidden');
    $('dec-pass-row').classList.add('hidden');
    $('dec-progwrap').classList.add('hidden');
    $('dec-prog').value = 0;
    $('dec-submit').disabled = true;
    decErr('');
    if (!hasCrypto) { $('dec-file').disabled = true; decErr(t('dec.noCrypto')); }
    else { $('dec-file').disabled = false; }
    $('dec-overlay').classList.remove('hidden');
  }
  function closeDecModal() { $('dec-overlay').classList.add('hidden'); }

  function saveBlob(blob, name) {
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = name || 'decrypted';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 30000);
  }
  // Accepts a raw key or a link/text containing "#k=" / "&k=".
  function keyFromInput(v) {
    v = String(v || '').trim();
    var m = /[#&]k=([A-Za-z0-9\-_]+)/.exec(v);
    return m ? m[1] : v;
  }

  if ($('decrypt-btn')) $('decrypt-btn').addEventListener('click', function () {
    closeUserMenu();
    openDecModal();
  });
  if ($('dec-close')) $('dec-close').addEventListener('click', closeDecModal);
  if ($('dec-cancel')) $('dec-cancel').addEventListener('click', closeDecModal);
  if ($('dec-overlay')) $('dec-overlay').addEventListener('click', function (e) {
    if (e.target === $('dec-overlay')) closeDecModal();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && $('dec-overlay') && !$('dec-overlay').classList.contains('hidden')) closeDecModal();
  });

  // On file pick: read it and inspect the container to know which secret to ask.
  if ($('dec-file')) $('dec-file').addEventListener('change', function () {
    if (!hasCrypto) return;
    decErr('');
    decFile = null; decMode = null;
    $('dec-key-row').classList.add('hidden');
    $('dec-pass-row').classList.add('hidden');
    $('dec-submit').disabled = true;
    var f = $('dec-file').files[0];
    if (!f) return;
    // Read only the header (first bytes) to detect the mode — not the whole file.
    f.slice(0, 128).arrayBuffer().then(function (buf) {
      var info = C.inspect(buf); // throws on bad magic
      decFile = f;
      decMode = info.mode;
      if (decMode === 'pass') { $('dec-pass-row').classList.remove('hidden'); $('dec-pass').focus(); }
      else { $('dec-key-row').classList.remove('hidden'); $('dec-key').focus(); }
      $('dec-submit').disabled = false;
    }).catch(function () { decErr(t('dec.notDxe')); });
  });

  function getKey(mode, salt) {
    if (mode === 'pass') {
      var p = $('dec-pass').value;
      if (!p) return Promise.reject(new Error('nopass'));
      return C.deriveKey(p, salt);
    }
    var k = keyFromInput($('dec-key').value);
    if (!k) return Promise.reject(new Error('nokey'));
    return C.importRawKey(C.b64urlDecode(k));
  }

  if ($('dec-form')) $('dec-form').addEventListener('submit', function (e) {
    e.preventDefault();
    decErr('');
    if (!decFile) { decErr(t('dec.notDxe')); return; }
    if (decMode === 'pass' && !$('dec-pass').value) { decErr(t('dec.needPass')); return; }
    if (decMode === 'key' && !keyFromInput($('dec-key').value)) { decErr(t('dec.needKey')); return; }

    var submit = $('dec-submit');
    submit.disabled = true;
    $('dec-progwrap').classList.remove('hidden');
    $('dec-progtext').textContent = t('dec.decrypting');
    $('dec-prog').value = 0;

    C.decrypt(decFile, getKey, function (frac) {
      $('dec-prog').value = Math.max(0, Math.min(1, frac));
    }).then(function (res) {
      saveBlob(res.blob, res.name);
      submit.disabled = false;
      closeDecModal();
      toast(t('dec.done'), 'ok');
    }).catch(function (err) {
      submit.disabled = false;
      $('dec-progwrap').classList.add('hidden');
      if (err && err.message === 'nopass') { decErr(t('dec.needPass')); return; }
      if (err && err.message === 'nokey') { decErr(t('dec.needKey')); return; }
      decErr(t('dec.badKey')); // wrong key/passphrase or corrupted container
    });
  });
})();

// ==================================================================
// Admin accounts (owner only) + audit log
// ==================================================================
(function () {
  // ---------------- Accounts ----------------
  function accErr(msg) { const e = $('accounts-error'); e.textContent = msg || ''; e.classList.toggle('hidden', !msg); }
  function closeAccounts() { $('accounts-overlay').classList.add('hidden'); }

  async function openAccounts() {
    closeUserMenu();
    $('acc-username').value = '';
    $('acc-password').value = '';
    accErr('');
    $('accounts-overlay').classList.remove('hidden');
    await refreshAccounts();
  }

  async function refreshAccounts() {
    try {
      const data = await api('GET', '/api/accounts');
      renderAccounts(data.accounts || [], data.self);
    } catch (e) {
      if (e.message !== 'not-authenticated') accErr(t('acc.loadFail'));
    }
  }

  function renderAccounts(accounts, selfId) {
    const box = $('accounts-list');
    box.textContent = '';
    accounts.forEach((a) => {
      const row = el('div', { class: 'acc-row' });
      const info = el('div', { class: 'acc-info' });
      const nameLine = el('div', { class: 'acc-name' });
      nameLine.appendChild(el('strong', { text: a.username }));
      nameLine.appendChild(el('span', { class: 'acc-badge ' + a.role, text: t('acc.role.' + a.role) }));
      if (a.twoFactor) nameLine.appendChild(el('span', { class: 'acc-badge tf', text: t('acc.tfOn') }));
      if (a.id === selfId) nameLine.appendChild(el('span', { class: 'acc-badge self', text: t('acc.you') }));
      info.appendChild(nameLine);
      const meta = [];
      if (a.lastLoginAt) meta.push(t('acc.lastLogin', { v: timeAgo(a.lastLoginAt) }));
      if (a.createdBy) meta.push(t('acc.createdBy', { v: a.createdBy }));
      if (a.isEnvManaged) meta.push(t('acc.envManaged'));
      info.appendChild(el('div', { class: 'acc-meta', text: meta.join(' · ') }));
      row.appendChild(info);

      const actions = el('div', { class: 'acc-actions' });
      // Any non-env account can be renamed (owner included) and have its password reset.
      if (!a.isEnvManaged) {
        const rename = el('button', { class: 'btn ghost sm', text: t('acc.rename') });
        rename.addEventListener('click', () => renameAccount(a, a.id === selfId));
        actions.appendChild(rename);
        const reset = el('button', { class: 'btn ghost sm', text: t('acc.reset') });
        reset.addEventListener('click', () => resetAccount(a));
        actions.appendChild(reset);
      }
      if (a.role !== 'owner' && a.id !== selfId) {
        const del = el('button', { class: 'btn ghost sm danger', text: t('acc.delete') });
        del.addEventListener('click', () => deleteAccount(a));
        actions.appendChild(del);
      }
      row.appendChild(actions);
      box.appendChild(row);
    });
  }

  async function renameAccount(a, isSelf) {
    const name = prompt(t('acc.renamePrompt', { u: a.username }), a.username);
    if (name == null) return;
    const username = String(name).trim().toLowerCase();
    if (username === a.username) return;
    if (!/^[a-z0-9._-]{3,40}$/.test(username)) { accErr(t('acc.badUsername')); return; }
    try {
      await api('POST', '/api/accounts/' + encodeURIComponent(a.id) + '/username', { username });
      accErr('');
      toast(t('acc.renamed'), 'ok');
      if (isSelf) {
        // Renamed the signed-in account: refresh the menu label + login prefill.
        state.username = username;
        document.querySelectorAll('.current-username').forEach((e) => { e.textContent = username; });
        try { localStorage.setItem('dxuser', username); } catch (_) {}
      }
      refreshAccounts();
    } catch (e2) {
      const code = e2.data && e2.data.error;
      accErr(code === 'username-taken' ? t('acc.taken') : code === 'invalid-username' ? t('acc.badUsername') : t('acc.actionFail'));
    }
  }

  async function deleteAccount(a) {
    if (!confirm(t('acc.confirmDelete', { u: a.username }))) return;
    try {
      await api('DELETE', '/api/accounts/' + encodeURIComponent(a.id));
      toast(t('acc.deleted'), 'ok');
      refreshAccounts();
    } catch (e) {
      if (e.message !== 'not-authenticated') accErr(t('acc.actionFail'));
    }
  }

  async function resetAccount(a) {
    if (!confirm(t('acc.resetPrompt', { u: a.username }))) return;
    try {
      const result = await api('POST', '/api/accounts/' + encodeURIComponent(a.id) + '/password', {});
      toast(t('acc.resetDone'), 'ok');
      accErr('');
      if (result && result.temporaryPassword) prompt(t('acc.resetGenerated'), result.temporaryPassword);
      refreshAccounts();
    } catch (e) {
      if (e.message !== 'not-authenticated') accErr(t('acc.actionFail'));
    }
  }

  if ($('accounts-btn')) $('accounts-btn').addEventListener('click', openAccounts);
  if ($('accounts-close')) $('accounts-close').addEventListener('click', closeAccounts);
  if ($('accounts-overlay')) $('accounts-overlay').addEventListener('click', (e) => {
    if (e.target === $('accounts-overlay')) closeAccounts();
  });

  if ($('account-form')) $('account-form').addEventListener('submit', async (e) => {
    e.preventDefault();
    accErr('');
    const username = $('acc-username').value.trim().toLowerCase();
    const password = $('acc-password').value;
    if (!/^[a-z0-9._-]{3,40}$/.test(username)) { accErr(t('acc.badUsername')); return; }
    if (password.length < 8) { accErr(t('acc.pwShort')); return; }
    const role = $('acc-role') ? $('acc-role').value : 'admin';
    try {
      await api('POST', '/api/accounts', { username, password, role });
      $('acc-username').value = '';
      $('acc-password').value = '';
      if ($('acc-role')) $('acc-role').value = 'admin';
      toast(t('acc.created'), 'ok');
      refreshAccounts();
    } catch (e2) {
      const code = e2.data && e2.data.error;
      accErr(code === 'username-taken' ? t('acc.taken') : code === 'invalid-username' ? t('acc.badUsername') : code === 'too-short' ? t('acc.pwShort') : t('acc.actionFail'));
    }
  });

  // ---------------- Security center & active sessions ----------------
  function closeSecurity(){const o=$('security-overlay');if(o)o.classList.add('hidden');}
  function renderSecurityOverview(data){
    const sessionsBox=$('security-sessions'),historyBox=$('security-history'),summary=$('security-summary');
    if(summary)summary.textContent=t('security.sessionCount',{n:(data.sessions||[]).length});
    if(sessionsBox){sessionsBox.textContent='';const rows=data.sessions||[];if(!rows.length)sessionsBox.appendChild(el('div',{class:'empty',text:t('security.none')}));else rows.forEach((sess)=>{const row=el('div',{class:'security-session-row'+(sess.current?' current':'')});const main=el('div',{class:'security-session-main'});const title=el('div',{class:'security-session-title'});title.append(el('strong',{text:sess.username||'—'}));if(sess.current)title.append(el('span',{class:'badge',text:t('security.current')}));main.append(title,el('span',{class:'muted sm',text:[sess.device||'—',sess.ip||'—'].join(' · ')}),el('span',{class:'muted sm',text:`${t('security.signedIn')}: ${sess.authenticatedAt?formatDate(sess.authenticatedAt):'—'} · ${t('security.lastSeen')}: ${sess.lastSeenAt?timeAgo(sess.lastSeenAt):'—'} · ${t('security.expires')}: ${sess.expires?formatDate(sess.expires):'—'}`}));row.appendChild(main);if(sess.canRevoke){const b=el('button',{class:'btn ghost sm',text:t('security.revoke'),attrs:{type:'button'}});b.addEventListener('click',async()=>{if(!confirm(t('security.revokeConfirm')))return;const password=prompt(t('security.reauthPassword'));if(password==null)return;b.disabled=true;try{const r=await api('DELETE','/api/security/sessions/'+encodeURIComponent(sess.id),{password});if(r.current){location.reload();return;}await loadSecurityOverview();}catch(e3){toast((e3.data&&e3.data.error)==='reauth-failed'?t('security.reauthFailed'):t('security.revokeFail'),'err');b.disabled=false;}});row.appendChild(b);}sessionsBox.appendChild(row);});}
    if(historyBox){historyBox.textContent='';const rows=data.history||[];if(!rows.length)historyBox.appendChild(el('div',{class:'empty',text:t('security.noHistory')}));else rows.forEach((e2)=>{const row=el('div',{class:'audit-row'});row.appendChild(el('span',{class:'audit-act',text:localizedAuditAction(e2.action)}));const mid=el('div',{class:'audit-mid'}),who=el('div',{class:'audit-who'});who.appendChild(el('span',{class:'audit-actor',text:e2.actor||'—'}));if(e2.detail)who.appendChild(el('span',{class:'audit-detail',text:localizedLogText(e2.detail)}));mid.append(who,el('div',{class:'audit-meta',text:(e2.ip?e2.ip+' · ':'')+formatDate(e2.at)}));row.appendChild(mid);historyBox.appendChild(row);});}
  }
  async function loadSecurityOverview(){try{renderSecurityOverview(await api('GET','/api/security/overview'));}catch(e){if(e.message!=='not-authenticated')toast(t('audit.loadFail'),'err');}}
  async function openSecurity(){closeUserMenu();const o=$('security-overlay');if(o)o.classList.remove('hidden');await loadSecurityOverview();}
  if($('security-btn'))$('security-btn').addEventListener('click',openSecurity);
  if($('security-close'))$('security-close').addEventListener('click',closeSecurity);
  if($('security-overlay'))$('security-overlay').addEventListener('click',(e)=>{if(e.target===$('security-overlay'))closeSecurity();});

  // ---------------- Audit log ----------------
  function closeAudit() { $('audit-overlay').classList.add('hidden'); }
  async function openAudit() {
    closeUserMenu();
    $('audit-list').textContent = '';
    $('audit-overlay').classList.remove('hidden');
    try {
      const data = await api('GET', '/api/audit?limit=200');
      renderAuditIntegrity(data.integrity);
      renderAudit(data.entries || []);
    } catch (e) {
      if (e.message !== 'not-authenticated') $('audit-list').appendChild(el('div', { class: 'empty', text: t('audit.loadFail') }));
    }
  }

  function renderAuditIntegrity(info) {
    const box = $('audit-integrity'); if (!box) return;
    if (!info) { box.textContent = t('audit.verifying'); box.className = 'muted sm'; return; }
    if (info.ok) {
      box.textContent = t('audit.integrityOk', { n: info.entries || 0, seq: info.headSeq || 0 });
      box.className = 'sm audit-integrity-ok';
    } else {
      box.textContent = t('audit.integrityBad', { reason: info.reason || 'unknown' });
      box.className = 'sm audit-integrity-bad';
    }
  }
  async function verifyAuditIntegrity() {
    const box = $('audit-integrity'); if (box) { box.textContent = t('audit.verifying'); box.className = 'muted sm'; }
    try { const r = await api('GET', '/api/audit/verify'); renderAuditIntegrity(r.integrity); }
    catch (_) { renderAuditIntegrity({ ok:false, reason:'verification-failed' }); }
  }

  function actionLabel(action) {
    return localizedAuditAction(action);
  }

  function renderAudit(entries) {
    const box = $('audit-list');
    box.textContent = '';
    if (!entries.length) { box.appendChild(el('div', { class: 'empty', text: t('audit.none') })); return; }
    entries.forEach((e2) => {
      const row = el('div', { class: 'audit-row' });
      row.appendChild(el('span', { class: 'audit-act', text: actionLabel(e2.action) }));
      const mid = el('div', { class: 'audit-mid' });
      const who = el('div', { class: 'audit-who' });
      who.appendChild(el('span', { class: 'audit-actor', text: e2.actor || '—' }));
      if (e2.detail) who.appendChild(el('span', { class: 'audit-detail', text: localizedLogText(e2.detail) }));
      mid.appendChild(who);
      mid.appendChild(el('div', { class: 'audit-meta', text: (e2.ip ? e2.ip + ' · ' : '') + formatDate(e2.at) }));
      row.appendChild(mid);
      box.appendChild(row);
    });
  }

  if ($('audit-btn')) $('audit-btn').addEventListener('click', openAudit);
  if ($('audit-verify')) $('audit-verify').addEventListener('click', verifyAuditIntegrity);
  if ($('audit-close')) $('audit-close').addEventListener('click', closeAudit);
  if ($('audit-overlay')) $('audit-overlay').addEventListener('click', (e) => {
    if (e.target === $('audit-overlay')) closeAudit();
  });

  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    if ($('accounts-overlay') && !$('accounts-overlay').classList.contains('hidden')) closeAccounts();
    if ($('security-overlay') && !$('security-overlay').classList.contains('hidden')) closeSecurity();
    if ($('dlp-details-overlay') && !$('dlp-details-overlay').classList.contains('hidden')) closeDlpDetails();
    if ($('audit-overlay') && !$('audit-overlay').classList.contains('hidden')) closeAudit();
  });
})();

// ------------------------------------------------------------------
// Nominative sub-links (recipients): one token per person for a share.
// ------------------------------------------------------------------
// --- Edit an existing link ---
let editShareId = null;
function openEditModal(s) {
  editShareId = s.id;
  $('edit-name-label').textContent = s.name;
  $('edit-name').value = s.name || '';
  $('edit-expiry').value = 'keep'; // default: don't touch the expiry
  // Start the exact-date field EMPTY. Prefilling it would make an
  // untouched absolute date silently override the preset dropdown on save (the
  // server prefers expiresAt), so picking "Never"/"7 days" would be ignored.
  if ($('edit-expireat')) $('edit-expireat').value = '';
  $('edit-startsat').value = s.startsAt ? toLocalDatetime(new Date(s.startsAt)) : '';
  $('edit-maxdl').value = s.maxDownloads ? String(s.maxDownloads) : '';
  $('edit-maxvisitors').value = s.maxVisitors ? String(s.maxVisitors) : '';
  if ($('edit-dlthreshold')) $('edit-dlthreshold').value = s.notifyDownloadThreshold ? String(s.notifyDownloadThreshold) : ''; // download-goal alert
  if ($('edit-maxdlperip')) $('edit-maxdlperip').value = s.maxDownloadsPerIp ? String(s.maxDownloadsPerIp) : '';
  if ($('edit-maxbytesserved')) $('edit-maxbytesserved').value = s.maxBytesServed ? String(Math.round(s.maxBytesServed / 1073741824 * 100) / 100) : '';
  if ($('edit-emoji')) $('edit-emoji').value = s.emoji || '';
  if ($('edit-pwhint')) $('edit-pwhint').value = s.pwHint || '';
  $('edit-password').value = '';
  $('edit-password').placeholder = s.hasPassword ? t('ed.pwSet') : t('ed.pwPh');
  $('edit-clearpw').checked = false;
  $('edit-clearpw').parentElement.classList.toggle('hidden', !s.hasPassword); // only when one exists
  $('edit-rate').value = s.rateKBps ? String(s.rateKBps) : '';
  $('edit-allowzip').checked = s.webStorage ? false : s.allowZip !== false;
  $('edit-allowzip').disabled = !!s.webStorage;
  $('edit-preview').checked = !s.noPreview;
  $('edit-burn').checked = !!s.burnAfterDownload;
  // The access gate applies to file + folder download links (both go
  // through requireActiveShare). The feedback form is rendered on the
  // file/collection page only, so it's offered for 'file' shares (single or bundle),
  // not folders. Hidden entirely for reception/collab/image links.
  const gateType = s.type === 'file' || s.type === 'folder' || s.type === 'web-storage';
  const fbType = s.type === 'file' || (s.type === 'web-storage' && !(s.webStorage && s.webStorage.isDir));
  if ($('edit-requestaccess')) { $('edit-requestaccess').checked = !!s.requestAccess; $('edit-requestaccess').parentElement.classList.toggle('hidden', !gateType); }
  if ($('edit-feedback')) { $('edit-feedback').checked = !!s.allowFeedback; $('edit-feedback').parentElement.classList.toggle('hidden', !fbType); }
  if ($('edit-color')) $('edit-color').value = s.color || '';
  if ($('edit-tags')) $('edit-tags').value = Array.isArray(s.tags) ? s.tags.join(', ') : '';
  if ($('edit-description')) $('edit-description').value = s.descriptionMd || '';
  if ($('edit-reminder')) $('edit-reminder').value = s.expiryReminderHours == null ? '' : String(s.expiryReminderHours);
  if ($('edit-firstuse')) $('edit-firstuse').value = s.firstUseExpirySeconds ? String(Math.round((s.firstUseExpirySeconds / 3600) * 10) / 10) : '';
  if ($('edit-inactive')) $('edit-inactive').value = s.inactiveExpirySeconds ? String(Math.round((s.inactiveExpirySeconds / 86400) * 10) / 10) : '';
  // Access rules
  $('edit-geomode').value = s.geoMode || 'off';
  $('edit-geocountries').value = Array.isArray(s.geoCountries) ? s.geoCountries.join(', ') : '';
  $('edit-ipmode').value = s.ipMode || 'off';
  $('edit-iplist').value = Array.isArray(s.ipList) ? s.ipList.join(', ') : '';
  if ($('edit-note')) $('edit-note').value = s.note || '';
  const rx = s.inbox || s.collab || null;
  if ($('edit-reception-options')) $('edit-reception-options').classList.toggle('hidden', !rx);
  if (rx) {
    $('edit-rx-maxfiles').value = rx.maxFiles || '';
    $('edit-rx-maxfilesupload').value = rx.maxFilesPerUpload || '';
    $('edit-rx-maxfilemb').value = rx.maxFileBytes ? String(Math.round(rx.maxFileBytes / 1048576 * 100) / 100) : '';
    $('edit-rx-maxtotalmb').value = rx.maxTotalBytes ? String(Math.round(rx.maxTotalBytes / 1048576 * 100) / 100) : '';
    $('edit-rx-maxfilessender').value = rx.maxFilesPerSender || '';
    $('edit-rx-maxmbsender').value = rx.maxBytesPerSender ? String(Math.round(rx.maxBytesPerSender / 1048576 * 100) / 100) : '';
    $('edit-rx-allowext').value = Array.isArray(rx.allowExt) ? rx.allowExt.join(', ') : '';
    $('edit-rx-blockext').value = Array.isArray(rx.blockExt) ? rx.blockExt.join(', ') : '';
    $('edit-rx-groupsender').checked = !!rx.groupBySender; $('edit-rx-tagsender').checked = !!rx.tagBySender;
    $('edit-rx-rejectdup').checked = !!rx.rejectDuplicates; $('edit-rx-requiresender').checked = !!rx.requireSenderName;
    $('edit-rx-rejectdup').disabled = !!s.webStorage;
    $('edit-rx-blockexec').checked = !!rx.blockExecutables; $('edit-rx-moderated').checked = !!rx.moderated;
    $('edit-rx-moderated').disabled = !!s.webStorage;
    $('edit-rx-allowdelete').checked = !!rx.allowDelete; $('edit-rx-allowdelete-row').classList.toggle('hidden', s.type !== 'collab');
  }
  $('edit-error').classList.add('hidden');
  $('edit-overlay').classList.remove('hidden');
  const editBody = $('edit-modal-body');
  if (editBody) editBody.scrollTop = 0;
}
function closeEditModal() { $('edit-overlay').classList.add('hidden'); editShareId = null; }
if ($('edit-close')) $('edit-close').addEventListener('click', closeEditModal);
if ($('edit-cancel')) $('edit-cancel').addEventListener('click', closeEditModal);
if ($('edit-overlay')) $('edit-overlay').addEventListener('click', (e) => {
  if (e.target === $('edit-overlay')) closeEditModal();
});
if ($('edit-save')) $('edit-save').addEventListener('click', async () => {
  if (!editShareId) return;
  const editRateRaw = String($('edit-rate').value || '').trim();
  const editRateKBps = editRateRaw === '' ? 0 : Number(editRateRaw);
  if (!Number.isFinite(editRateKBps) || !Number.isInteger(editRateKBps) || editRateKBps < 0) {
    const err = $('edit-error'); err.textContent = t('ed.saveFail', { error:'invalid-rate' }); err.classList.remove('hidden'); $('edit-rate').focus(); return;
  }
  const payload = {
    name: $('edit-name').value,
    maxDownloads: parseInt($('edit-maxdl').value, 10) || 0,
    maxVisitors: parseInt($('edit-maxvisitors').value, 10) || 0,
    notifyDownloadThreshold: parseInt($('edit-dlthreshold') && $('edit-dlthreshold').value, 10) || 0, // download-goal alert
    maxDownloadsPerIp: parseInt($('edit-maxdlperip').value, 10) || 0,
    maxBytesServed: Math.round((parseFloat($('edit-maxbytesserved') && $('edit-maxbytesserved').value) || 0) * 1073741824), // (GB→bytes)
    emoji: $('edit-emoji') ? $('edit-emoji').value : '',
    pwHint: $('edit-pwhint') ? $('edit-pwhint').value : '',
    rateKBps: editRateKBps,
    allowZip: $('edit-allowzip').checked,
    noPreview: !$('edit-preview').checked,
    burnAfterDownload: $('edit-burn').checked,
    requestAccess: $('edit-requestaccess') ? $('edit-requestaccess').checked : false,
    allowFeedback: $('edit-feedback') ? $('edit-feedback').checked : false,
    color: $('edit-color') ? $('edit-color').value.trim() : '',
    tags: $('edit-tags') ? $('edit-tags').value.split(',').map((x) => x.trim()).filter(Boolean) : [],
    descriptionMd: $('edit-description') ? $('edit-description').value : '',
    expiryReminderHours: $('edit-reminder') && $('edit-reminder').value !== '' ? Number($('edit-reminder').value) : null,
    firstUseExpirySeconds: $('edit-firstuse') ? Math.max(0, Math.round((parseFloat($('edit-firstuse').value) || 0) * 3600)) : 0,
    inactiveExpirySeconds: $('edit-inactive') ? Math.max(0, Math.round((parseFloat($('edit-inactive').value) || 0) * 86400)) : 0,
    note: $('edit-note') ? $('edit-note').value : '',
    startsAt: startsAtMs('edit-startsat'),
    geoMode: $('edit-geomode').value,
    geoCountries: $('edit-geocountries').value,
    ipMode: $('edit-ipmode').value,
    ipList: $('edit-iplist').value,
  };
  if ($('edit-reception-options') && !$('edit-reception-options').classList.contains('hidden')) {
    const mb = (id) => Math.max(0, Math.round((parseFloat($(id).value) || 0) * 1048576));
    payload.maxFiles = parseInt($('edit-rx-maxfiles').value, 10) || 0;
    payload.maxFilesPerUpload = parseInt($('edit-rx-maxfilesupload').value, 10) || 0;
    payload.maxFileBytes = mb('edit-rx-maxfilemb'); payload.maxTotalBytes = mb('edit-rx-maxtotalmb');
    payload.maxFilesPerSender = parseInt($('edit-rx-maxfilessender').value, 10) || 0; payload.maxBytesPerSender = mb('edit-rx-maxmbsender');
    payload.allowExt = $('edit-rx-allowext').value; payload.blockExt = $('edit-rx-blockext').value;
    payload.groupBySender = $('edit-rx-groupsender').checked; payload.tagBySender = $('edit-rx-tagsender').checked;
    payload.rejectDuplicates = $('edit-rx-rejectdup').checked; payload.requireSenderName = $('edit-rx-requiresender').checked;
    payload.blockExecutables = $('edit-rx-blockexec').checked; payload.moderated = $('edit-rx-moderated').checked;
    payload.allowDelete = $('edit-rx-allowdelete').checked;
  }
  // Expiry: 'keep' leaves it untouched; any other value re-sets it (0 = never).
  const exp = $('edit-expiry').value;
  if (exp !== 'keep') payload.expiresInSeconds = parseInt(exp, 10) || 0;
  // An exact date, when provided, takes precedence over the preset.
  const exAt = expireAtMs('edit-expireat');
  if (exAt) payload.expiresAt = exAt;
  // Password: "remove" wins; else a typed value sets/replaces; blank = keep.
  if ($('edit-clearpw').checked) payload.password = ''; // server treats '' as clear
  else { const pw = $('edit-password').value; if (pw !== '') payload.password = pw; }
  try {
    const r = await api('PATCH', '/api/shares/' + encodeURIComponent(editShareId), payload);
    if (payload.password && r && r.share) rememberLinkPassword(r.share.url, payload.password);
    toast(t('ed.saved'), 'ok');
    closeEditModal();
    refreshShares();
    return r;
  } catch (e) {
    const err = $('edit-error');
    err.textContent = t('ed.saveFail', { error: (e.data && e.data.error) || e.message });
    err.classList.remove('hidden');
  }
});

function recipientsSection(s) {
  if (s.type === 'inbox' || s.type === 'collab') return null;
  const list = Array.isArray(s.recipients) ? s.recipients : [];
  const box = el('div', { class: 'recipients' });
  box.appendChild(el('div', { class: 'sl-label', text: t('rcp.label', { n: list.length }) }));

  list.forEach((r) => {
    const row = el('div', { class: 'rcp-row' });
    row.appendChild(el('span', { class: 'rcp-name', text: r.name }));
    // Read receipt: viewed / downloaded status.
    if (r.downloads > 0) {
      row.appendChild(el('span', { class: 'badge ok-badge rcp-status', text: t('rcp.downloaded') }));
    } else if (r.viewed) {
      row.appendChild(el('span', { class: 'badge rcp-status seen', text: t('rcp.viewed') }));
    } else {
      row.appendChild(el('span', { class: 'badge rcp-status pending', text: t('rcp.notSeen') }));
    }
    row.appendChild(el('span', { class: 'rcp-count', text: t('rcp.dl', { n: r.downloads || 0 }) }));
    const when = r.lastDownloadAt || r.lastViewAt;
    if (when) {
      const whereBits = [];
      if (r.lastViewCountry) whereBits.push(r.lastViewCountry);
      if (r.lastViewIp) whereBits.push(r.lastViewIp);
      row.appendChild(el('span', {
        class: 'rcp-when muted sm',
        text: timeAgo(when) + (whereBits.length ? ' · ' + whereBits.join(' · ') : ''),
      }));
    }
    row.appendChild(el('div', { class: 'link-box rcp-link', text: r.url || r.path }));
    const copyBtn = el('button', { class: 'btn ghost xs', text: t('sh.copy') });
    copyBtn.addEventListener('click', () => copy(r.url || r.path));
    row.appendChild(copyBtn);
    if (r.url) {
      const qrBtn = el('button', { class: 'btn ghost xs', text: t('sh.qr'), attrs: { title: t('sh.qrTitle') } });
      qrBtn.addEventListener('click', () => openQr({ name: s.name + ' \u2014 ' + r.name, url: r.url }));
      row.appendChild(qrBtn);
    }
    // Per-recipient overrides: own expiry / download cap.
    const lim = [];
    if (r.maxDownloads) lim.push('\u2b07 ' + (r.downloads || 0) + '/' + r.maxDownloads);
    if (r.expiresAt) lim.push('\u23f3 ' + formatDate(r.expiresAt));
    if (lim.length) row.appendChild(el('span', { class: 'rcp-lim muted sm', text: lim.join(' \u00b7 ') }));
    const limBtn = el('button', { class: 'btn ghost xs', text: '\u2699', attrs: { title: t('rcp.limitsTitle') } });
    limBtn.addEventListener('click', () => editRecipientLimits(s, r));
    row.appendChild(limBtn);
    const del = el('button', { class: 'btn danger xs', text: '\u2715', attrs: { title: t('rcp.remove') } });
    del.addEventListener('click', () => removeRecipient(s, r));
    row.appendChild(del);
    box.appendChild(row);
  });

  const add = el('div', { class: 'rcp-add' });
  const input = el('input', { class: 'rcp-input', attrs: { type: 'text', placeholder: t('rcp.addPh'), maxlength: '100' } });
  const addBtn = el('button', { class: 'btn ghost sm', text: t('rcp.add') });
  const submit = () => { const v = input.value.trim(); if (v) addRecipients(s, v); };
  addBtn.addEventListener('click', submit);
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); submit(); } });
  add.appendChild(input);
  add.appendChild(addBtn);
  box.appendChild(add);
  return box;
}

async function addRecipients(s, names) {
  try {
    await api('POST', '/api/shares/' + encodeURIComponent(s.id) + '/recipients', { names });
    toast(t('rcp.added'), 'ok');
    refreshShares();
  } catch (e) {
    toast((e.data && e.data.error === 'exists') ? t('rcp.exists') : t('rcp.addFail'), 'err');
  }
}

// Set a recipient's own download cap and/or expiry (0/blank = inherit).
async function editRecipientLimits(s, r) {
  const dl = prompt(t('rcp.maxDlPrompt', { name: r.name }), r.maxDownloads ? String(r.maxDownloads) : '');
  if (dl === null) return;
  const curDays = r.expiresAt ? String(Math.max(1, Math.ceil((r.expiresAt - Date.now()) / 86400000))) : '';
  const days = prompt(t('rcp.expiryPrompt', { name: r.name }), curDays);
  if (days === null) return;
  const n = parseInt(dl, 10), d = parseInt(days, 10);
  const body = {
    maxDownloads: Number.isFinite(n) && n > 0 ? n : 0,
    expiresInSeconds: Number.isFinite(d) && d > 0 ? d * 86400 : 0,
  };
  try {
    await api('PATCH', '/api/shares/' + encodeURIComponent(s.id) + '/recipients/' + encodeURIComponent(r.token), body);
    toast(t('rcp.limitsSaved'), 'ok');
    refreshShares();
  } catch (e) { toast(t('rcp.limitsFail'), 'err'); }
}

async function removeRecipient(s, r) {
  if (!confirm(t('rcp.removeConfirm', { name: r.name }))) return;
  try {
    await api('DELETE', '/api/shares/' + encodeURIComponent(s.id) + '/recipients/' + encodeURIComponent(r.token));
    toast(t('rcp.removed'), 'ok');
    loadUndoPreview();
    refreshShares();
  } catch (e) {
    toast(t('rcp.removeFail'), 'err');
  }
}

// ------------------------------------------------------------------
// Client nicknames: name a visitor by IP; shown next to the IP in the
// live-transfers and history views (click the IP to set/edit).
// ------------------------------------------------------------------
function ipTag(ip, ipName) {
  const span = el('span', { class: 'tip ip-tag', attrs: { title: t('ipn.clickHint') } });
  if (!ip) { span.textContent = '—'; return span; }
  if (ipName) span.appendChild(el('span', { class: 'ipn-name', text: ipName }));
  span.appendChild(el('span', { class: 'ipn-ip', text: ip }));
  span.addEventListener('click', () => renameIp(ip, ipName));
  return span;
}

async function renameIp(ip, current) {
  if (!ip) return;
  const name = prompt(t('ipn.prompt', { ip }), current || '');
  if (name === null) return; // cancelled
  const trimmed = name.trim();
  try {
    await api('POST', '/api/ip-names', { ip, name: trimmed });
    toast(trimmed ? t('ipn.saved') : t('ipn.cleared'), 'ok');
    refreshShares(); // re-fetch: nicknames refresh across transfers + history
    if (state.dashboardData) loadDashboard(); // and the dashboard's top clients
  } catch (e) {
    toast(t('ipn.fail'), 'err');
  }
}

// Public bridge for optional standard-view productivity modules. Keep the
// surface intentionally narrow: it exposes existing, role-aware UI actions but
// not authentication/session secrets.
window.DXStandard = Object.freeze({
  getState: () => state,
  t,
  api,
  toast,
  copy,
  refreshShares,
  openShareDetails,
  openDetailedStats,
  openEditModal,
  cloneShare,
  togglePause,
  toggleShareFlag,
  revokeShare,
  openShareChangeHistory,
  runDiagnostics,
  renderDiagnostics,
  loadDashboard,
  loadDashboardLive,
  formatBytes,
  formatDate,
  timeAgo,
});
